func convertErrDetailsToPayloads(details converter.EncodedValues, dc converter.DataConverter) *commonpb.Payloads {
	switch d := details.(type) {
	case ErrorDetailsValues:
		data, err := encodeArgs(dc, d)
		if err != nil {
			panic(err)
		}
		return data
	case *EncodedValues:
		return d.values
	default:
		panic(fmt.Sprintf("unknown error details type %T", details))
	}
}

// IsRetryable returns if error retryable or not.
func IsRetryable(err error, nonRetryableTypes []string) bool {
	if err == nil {
		return false
	}

	var terminatedErr *TerminatedError
	var canceledErr *CanceledError
	var workflowPanicErr *workflowPanicError
	if errors.As(err, &terminatedErr) || errors.As(err, &canceledErr) || errors.As(err, &workflowPanicErr) {
		return false
	}

	var timeoutErr *TimeoutError
	if errors.As(err, &timeoutErr) {
		return timeoutErr.timeoutType == enumspb.TIMEOUT_TYPE_START_TO_CLOSE || timeoutErr.timeoutType == enumspb.TIMEOUT_TYPE_HEARTBEAT
	}

	var applicationErr *ApplicationError
	var errType string
	if errors.As(err, &applicationErr) {
		if applicationErr.nonRetryable {
			return false
		}
		errType = applicationErr.errType
	} else {
		// If it is generic Go error.
		errType = getErrType(err)
	}

	return !slices.Contains(nonRetryableTypes, errType)
}

func getErrType(err error) string {
	var t reflect.Type
	for t = reflect.TypeOf(err); t.Kind() == reflect.Pointer; t = t.Elem() {
	}

	if t.Name() == goErrType {
		return ""
	}

	return t.Name()
}

func isBenignApplicationError(err error) bool {
	appError, _ := err.(*ApplicationError)
	return appError != nil && appError.Category() == ApplicationErrorCategoryBenign
}

func isBenignProtoApplicationFailure(failure *failurepb.Failure) bool {
	if failure == nil {
		return false
	}
	appFailureInfo := failure.GetApplicationFailureInfo()
	return appFailureInfo != nil && appFailureInfo.GetCategory() == enumspb.APPLICATION_ERROR_CATEGORY_BENIGN
}

package internal

import (
	"fmt"

	sdkpb "go.temporal.io/api/sdk/v1"

	"go.temporal.io/sdk/converter"
)

type eventGroupKind int

const (
	eventGroupKindLabel eventGroupKind = iota
	eventGroupKindInboundUpdate
)

// EventGroupOptions are optional settings for an explicit Event Group.
//
// NOTE: Experimental (Event Groups)
//
// Exposed as: [go.temporal.io/sdk/workflow.EventGroupOptions]
type EventGroupOptions struct {
	// Label is an optional display string for this group. When empty, the marker
	// carries only its ID and no label payload is emitted. When set, the label is
	// converted with the default payload converter (json/plain) and then given to
	// the workflow data converter as a raw value, so payload codecs run and the
	// label is not converted again. The ID itself is never codec-encoded.
	//
	// Do not put secrets in IDs. Labels may contain sensitive data because they
	// are codec-encoded.
	//
	// NOTE: Experimental (Event Groups)
	Label string
}

// EventGroup is a user-facing handle for an Event Group Marker.
//
// Note: Contrary to other SDKs, the Go SDK does not emit implicit Event Groups
// for inbound signals.
//
// NOTE: Experimental (Event Groups)
//
// Exposed as: [go.temporal.io/sdk/workflow.EventGroup]
type EventGroup struct {
	// ID is the group identity. An explicit group records the caller-supplied ID
	// verbatim. The implicit update group uses "inbound-update:" plus the update
	// ID. The marker variant is not derived from this string.
	//
	// Do not put secrets in IDs. The ID is never codec-encoded.
	//
	// NOTE: Experimental (Event Groups)
	ID string

	kind            eventGroupKind
	label           string
	inboundUpdateID string
}

type eventGroupsContextKey struct{}

// eventGroupFrame is the effective ambient set for one scope. groups is keyed
// by explicit group ID and already excludes later duplicates, so the earliest
// label for an ID wins. implicit is the update handler's group when one is
// active. It is not a label, so it stays out of that ID space. A nested scope
// copies groups so inserting into the child does not change the parent.
type eventGroupFrame struct {
	groups   map[string]EventGroup
	implicit *EventGroup
}

// NewEventGroup creates an explicit Event Group with the given ID and no label.
// The ID is recorded verbatim. It must not be empty.
//
// NOTE: Experimental (Event Groups)
//
// Exposed as: [go.temporal.io/sdk/workflow.NewEventGroup]
func NewEventGroup(id string) EventGroup {
	return NewEventGroupWithOptions(id, EventGroupOptions{})
}

// NewEventGroupWithOptions creates an explicit Event Group with the given ID
// and options.
//
// NOTE: Experimental (Event Groups)
//
// Exposed as: [go.temporal.io/sdk/workflow.NewEventGroupWithOptions]
func NewEventGroupWithOptions(id string, options EventGroupOptions) EventGroup {
	if id == "" {
		panic("event group ID must not be empty")
	}
	return EventGroup{
		kind:  eventGroupKindLabel,
		ID:    id,
		label: options.Label,
	}
}

func implicitUpdateEventGroup(updateID string) EventGroup {
	return EventGroup{
		kind:            eventGroupKindInboundUpdate,
		ID:              "inbound-update:" + updateID,
		inboundUpdateID: updateID,
	}
}

func (group EventGroup) toMarker(dc converter.DataConverter) (*sdkpb.EventGroupMarker, error) {
	switch group.kind {
	case eventGroupKindInboundUpdate:
		return &sdkpb.EventGroupMarker{
			Variant: &sdkpb.EventGroupMarker_InboundUpdate_{
				InboundUpdate: &sdkpb.EventGroupMarker_InboundUpdate{
					InboundUpdateId: group.inboundUpdateID,
				},
			},
		}, nil
	default:
		label := &sdkpb.EventGroupMarker_Label{Id: group.ID}
		if group.label != "" {
			payload, err := converter.GetDefaultDataConverter().ToPayload(group.label)
			if err != nil {
				return nil, fmt.Errorf("convert event group label: %w", err)
			}
			// Hand the default-converter payload to the workflow data converter as a
			// raw value so codecs apply without running user payload conversion.
			if dc != nil {
				payload, err = dc.ToPayload(converter.NewRawValue(payload))
				if err != nil {
					return nil, fmt.Errorf("encode event group label: %w", err)
				}
			}
			label.Label = payload
		}
		return &sdkpb.EventGroupMarker{Variant: &sdkpb.EventGroupMarker_Label_{Label: label}}, nil
	}
}

// WithEventGroups returns a derived context whose commands also carry groups.
// Nested calls are additive. Groups that share an identity collapse to the
// first one.
//
// NOTE: Experimental (Event Groups)
//
// Exposed as: [go.temporal.io/sdk/workflow.WithEventGroups]
func WithEventGroups(ctx Context, groups ...EventGroup) Context {
	if len(groups) == 0 {
		return ctx
	}
	parent := ambientFrame(ctx)
	frame := &eventGroupFrame{groups: make(map[string]EventGroup, len(groups))}
	if parent != nil {
		frame.implicit = parent.implicit
		if len(parent.groups) > 0 {
			frame.groups = make(map[string]EventGroup, len(parent.groups)+len(groups))
			for id, group := range parent.groups {
				frame.groups[id] = group
			}
		}
	}
	for _, group := range groups {
		if _, exists := frame.groups[group.ID]; exists {
			continue
		}
		frame.groups[group.ID] = group
	}
	return WithValue(ctx, eventGroupsContextKey{}, frame)
}

// withImplicitUpdateEventGroup replaces ambient groups with the update's
// implicit group. Handlers must not inherit an explicit scope that was active
// when the handler was registered or when the update was dispatched.
// A blank update ID fails the workflow task: the handler would otherwise run
// with neither an implicit group nor the surrounding explicit scope.
func withImplicitUpdateEventGroup(ctx Context, updateID string) Context {
	if updateID == "" {
		panic("update ID must not be empty")
	}
	group := implicitUpdateEventGroup(updateID)
	frame := &eventGroupFrame{implicit: &group}
	return WithValue(ctx, eventGroupsContextKey{}, frame)
}

func ambientFrame(ctx Context) *eventGroupFrame {
	frame, _ := ctx.Value(eventGroupsContextKey{}).(*eventGroupFrame)
	return frame
}

func ambientEventGroups(ctx Context) []EventGroup {
	frame := ambientFrame(ctx)
	if frame == nil {
		return nil
	}
	groups := make([]EventGroup, 0, len(frame.groups)+1)
	if frame.implicit != nil {
		groups = append(groups, *frame.implicit)
	}
	for _, group := range frame.groups {
		groups = append(groups, group)
	}
	return groups
}

func explicitAmbientEventGroups(ctx Context) []EventGroup {
	frame := ambientFrame(ctx)
	if frame == nil || len(frame.groups) == 0 {
		return nil
	}
	groups := make([]EventGroup, 0, len(frame.groups))
	for _, group := range frame.groups {
		groups = append(groups, group)
	}
	return groups
}

// mergeEventGroups unions explicit groups in order. The first group for an ID
// wins, including which label is kept when IDs collide. Implicit groups are
// not part of this ID space.
func mergeEventGroups(sets ...[]EventGroup) []EventGroup {
	seen := make(map[string]struct{})
	var merged []EventGroup
	for _, set := range sets {
		for _, group := range set {
			if _, ok := seen[group.ID]; ok {
				continue
			}
			seen[group.ID] = struct{}{}
			merged = append(merged, group)
		}
	}
	return merged
}

func mergeAmbientAndDirectEventGroups(ctx Context, direct []EventGroup) []EventGroup {
	explicit := mergeEventGroups(explicitAmbientEventGroups(ctx), direct)
	frame := ambientFrame(ctx)
	if frame == nil || frame.implicit == nil {
		return explicit
	}
	groups := make([]EventGroup, 0, len(explicit)+1)
	groups = append(groups, *frame.implicit)
	groups = append(groups, explicit...)
	return groups
}

func eventGroupMarkersToProto(ctx Context, direct []EventGroup) []*sdkpb.EventGroupMarker {
	groups := mergeAmbientAndDirectEventGroups(ctx, direct)
	if len(groups) == 0 {
		return nil
	}
	dc := GetDataConverterFromWorkflowContext(ctx)
	markers := make([]*sdkpb.EventGroupMarker, 0, len(groups))
	for _, group := range groups {
		marker, err := group.toMarker(dc)
		if err != nil {
			panic(fmt.Sprintf("failed to build event group marker: %v", err))
		}
		markers = append(markers, marker)
	}
	return markers
}

package internal

import (
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/nexus-rpc/sdk-go/nexus"
	"google.golang.org/protobuf/proto"
	"google.golang.org/protobuf/types/known/durationpb"

	commonpb "go.temporal.io/api/common/v1"
	enumspb "go.temporal.io/api/enums/v1"
	failurepb "go.temporal.io/api/failure/v1"

	"go.temporal.io/sdk/converter"
)

var defaultFailureConverter = NewDefaultFailureConverter(DefaultFailureConverterOptions{})

// GetDefaultFailureConverter returns the default failure converter used by Temporal.
//
// Exposed as: [go.temporal.io/sdk/temporal.GetDefaultFailureConverter]
func GetDefaultFailureConverter() converter.FailureConverter {
	return defaultFailureConverter
}

// DefaultFailureConverterOptions are optional parameters for DefaultFailureConverter creation.
//
// Exposed as: [go.temporal.io/sdk/temporal.DefaultFailureConverterOptions]
type DefaultFailureConverterOptions struct {
	// Optional: Sets DataConverter to customize serialization/deserialization of fields.
	// This converter is wrapped to support transfer type conversion.
	//
	// default: Default data converter
	DataConverter converter.DataConverter

	// Optional: Whether to encode error messages and stack traces.
	//
	// default: false
	EncodeCommonAttributes bool
}

// DefaultFailureConverter seralizes errors with the option to encode common parameters under Failure.EncodedAttributes
//
// Exposed as: [go.temporal.io/sdk/temporal.DefaultFailureConverter]
type DefaultFailureConverter struct {
	dataConverter          converter.DataConverter
	encodeCommonAttributes bool
}

// NewDefaultFailureConverter creates new instance of DefaultFailureConverter.
//
// Exposed as: [go.temporal.io/sdk/temporal.NewDefaultFailureConverter]
func NewDefaultFailureConverter(opt DefaultFailureConverterOptions) *DefaultFailureConverter {
	opt.DataConverter = MakeTransferAware(opt.DataConverter)
	return &DefaultFailureConverter{
		dataConverter:          opt.DataConverter,
		encodeCommonAttributes: opt.EncodeCommonAttributes,
	}
}

// ErrorToFailure converts an error to a Failure
func (dfc *DefaultFailureConverter) ErrorToFailure(err error) *failurepb.Failure {
	if err == nil {
		return nil
	}

	if fh, ok := err.(failureHolder); ok {
		if fh.failure() != nil {
			return fh.failure()
		}
	}

	failure := &failurepb.Failure{
		Source: "GoSDK",
	}

	if m, ok := err.(messenger); ok && m != nil {
		failure.Message = m.message()
	} else {
		failure.Message = err.Error()
	}

	switch err := err.(type) {
	case *ApplicationError:
		var delay *durationpb.Duration
		if err.nextRetryDelay != 0 {
			delay = durationpb.New(err.nextRetryDelay)
		}
		failureInfo := &failurepb.ApplicationFailureInfo{
			Type:           err.errType,
			NonRetryable:   err.NonRetryable(),
			Details:        convertErrDetailsToPayloads(err.details, dfc.dataConverter),
			NextRetryDelay: delay,
			Category:       enumspb.ApplicationErrorCategory(err.Category()),
		}
		failure.FailureInfo = &failurepb.Failure_ApplicationFailureInfo{ApplicationFailureInfo: failureInfo}
	case *CanceledError:
		failureInfo := &failurepb.CanceledFailureInfo{
			Details: convertErrDetailsToPayloads(err.details, dfc.dataConverter),
		}
		failure.FailureInfo = &failurepb.Failure_CanceledFailureInfo{CanceledFailureInfo: failureInfo}
	case *PanicError:
		failureInfo := &failurepb.ApplicationFailureInfo{
			Type: getErrType(err),
		}
		failure.FailureInfo = &failurepb.Failure_ApplicationFailureInfo{ApplicationFailureInfo: failureInfo}
		failure.StackTrace = err.StackTrace()
	case *workflowPanicError:
		failureInfo := &failurepb.ApplicationFailureInfo{
			Type:         getErrType(&PanicError{}),
			NonRetryable: true,
		}
		failure.FailureInfo = &failurepb.Failure_ApplicationFailureInfo{ApplicationFailureInfo: failureInfo}
		failure.StackTrace = err.StackTrace()
	case *TimeoutError:
		failureInfo := &failurepb.TimeoutFailureInfo{
			TimeoutType:          err.timeoutType,
			LastHeartbeatDetails: convertErrDetailsToPayloads(err.lastHeartbeatDetails, dfc.dataConverter),
		}
		failure.FailureInfo = &failurepb.Failure_TimeoutFailureInfo{TimeoutFailureInfo: failureInfo}
	case *TerminatedError:
		failureInfo := &failurepb.TerminatedFailureInfo{}
		failure.FailureInfo = &failurepb.Failure_TerminatedFailureInfo{TerminatedFailureInfo: failureInfo}
	case *ServerError:
		failureInfo := &failurepb.ServerFailureInfo{
			NonRetryable: err.nonRetryable,
		}
		failure.FailureInfo = &failurepb.Failure_ServerFailureInfo{ServerFailureInfo: failureInfo}
	case *ActivityError:
		failureInfo := &failurepb.ActivityFailureInfo{
			ScheduledEventId: err.scheduledEventID,
			StartedEventId:   err.startedEventID,
			Identity:         err.identity,
			ActivityType:     err.activityType,
			ActivityId:       err.activityID,
			RetryState:       err.retryState,
		}
		failure.FailureInfo = &failurepb.Failure_ActivityFailureInfo{ActivityFailureInfo: failureInfo}
	case *ChildWorkflowExecutionError:
		failureInfo := &failurepb.ChildWorkflowExecutionFailureInfo{
			Namespace: err.namespace,
			WorkflowExecution: &commonpb.WorkflowExecution{
				WorkflowId: err.workflowID,
				RunId:      err.runID,
			},
			WorkflowType:     &commonpb.WorkflowType{Name: err.workflowType},
			InitiatedEventId: err.initiatedEventID,
			StartedEventId:   err.startedEventID,
			RetryState:       err.retryState,
		}
		failure.FailureInfo = &failurepb.Failure_ChildWorkflowExecutionFailureInfo{ChildWorkflowExecutionFailureInfo: failureInfo}
	case *NexusOperationError:
		var token = err.OperationToken
		failureInfo := &failurepb.NexusOperationFailureInfo{
			ScheduledEventId: err.ScheduledEventID,
			Endpoint:         err.Endpoint,
			Service:          err.Service,
			Operation:        err.Operation,
			//lint:ignore SA1019 populate the legacy operation ID for backwards-compatible failure decoding
			OperationId:    token,
			OperationToken: token,
		}
		failure.FailureInfo = &failurepb.Failure_NexusOperationExecutionFailureInfo{NexusOperationExecutionFailureInfo: failureInfo}
	case *nexus.HandlerError:
		if err.OriginalFailure != nil {
			f, err := nexusFailureToTemporalFailure(*err.OriginalFailure, true)
			// If there was an error converting the original failure, we will ignore it
			// since we don't want to fail the entire conversion just because we couldn't convert the original failure.
			if err == nil {
				return f
			}
		}
		var retryBehavior enumspb.NexusHandlerErrorRetryBehavior
		switch err.RetryBehavior {
		case nexus.HandlerErrorRetryBehaviorRetryable:
			retryBehavior = enumspb.NEXUS_HANDLER_ERROR_RETRY_BEHAVIOR_RETRYABLE
		case nexus.HandlerErrorRetryBehaviorNonRetryable:
			retryBehavior = enumspb.NEXUS_HANDLER_ERROR_RETRY_BEHAVIOR_NON_RETRYABLE
		}
		failureInfo := &failurepb.NexusHandlerFailureInfo{
			Type:          string(err.Type),
			RetryBehavior: retryBehavior,
		}
		failure.FailureInfo = &failurepb.Failure_NexusHandlerFailureInfo{NexusHandlerFailureInfo: failureInfo}
		failure.StackTrace = err.StackTrace
		// Copy the message if present, if not we will keep the default message set above
		if len(err.Message) > 0 {
			failure.Message = err.Message
		}
	default: // All unknown errors are considered to be retryable ApplicationFailureInfo.
		failureInfo := &failurepb.ApplicationFailureInfo{
			Type:         getErrType(err),
			NonRetryable: false,
		}
		failure.FailureInfo = &failurepb.Failure_ApplicationFailureInfo{ApplicationFailureInfo: failureInfo}
	}

	failure.Cause = dfc.ErrorToFailure(errors.Unwrap(err))

	if dfc.encodeCommonAttributes {
		err := converter.EncodeCommonFailureAttributes(dfc.dataConverter, failure)
		if err != nil {
			panic(err)
		}
	}
	return failure
}

// FailureToError converts an Failure to an error
func (dfc *DefaultFailureConverter) FailureToError(failure *failurepb.Failure) error {
	if failure == nil {
		return nil
	}
	// Copy the original future to pass to the failureHolder
	originalFailure := proto.Clone(failure).(*failurepb.Failure)
	converter.DecodeCommonFailureAttributes(dfc.dataConverter, failure)

	message := failure.GetMessage()
	stackTrace := failure.GetStackTrace()
	var err error

	if failure.GetApplicationFailureInfo() != nil {
		applicationFailureInfo := failure.GetApplicationFailureInfo()
		details := newEncodedValues(applicationFailureInfo.GetDetails(), dfc.dataConverter)
		switch applicationFailureInfo.GetType() {
		case getErrType(&PanicError{}):
			err = newPanicError(message, stackTrace)
		default:
			var nextRetryDelay time.Duration
			if delay := applicationFailureInfo.GetNextRetryDelay(); delay != nil {
				nextRetryDelay = delay.AsDuration()
			}
			err = NewApplicationErrorWithOptions(
				message,
				applicationFailureInfo.GetType(),
				ApplicationErrorOptions{
					NonRetryable:   applicationFailureInfo.GetNonRetryable(),
					Cause:          dfc.FailureToError(failure.GetCause()),
					Details:        []any{details},
					NextRetryDelay: nextRetryDelay,
					Category:       ApplicationErrorCategory(applicationFailureInfo.GetCategory()),
				},
			)
		}
	} else if failure.GetCanceledFailureInfo() != nil {
		details := newEncodedValues(failure.GetCanceledFailureInfo().GetDetails(), dfc.dataConverter)
		err = NewCanceledErrorWithOptions(
			CanceledErrorOptions{
				Message: message,
				Details: []any{details},
				Cause:   dfc.FailureToError(failure.GetCause()),
			},
		)
	} else if failure.GetTimeoutFailureInfo() != nil {
		timeoutFailureInfo := failure.GetTimeoutFailureInfo()
		lastHeartbeatDetails := newEncodedValues(timeoutFailureInfo.GetLastHeartbeatDetails(), dfc.dataConverter)
		err = NewTimeoutError(
			message,
			timeoutFailureInfo.GetTimeoutType(),
			dfc.FailureToError(failure.GetCause()),
			lastHeartbeatDetails)
	} else if failure.GetTerminatedFailureInfo() != nil {
		err = newTerminatedError()
	} else if failure.GetServerFailureInfo() != nil {
		err = NewServerError(message, failure.GetServerFailureInfo().GetNonRetryable(), dfc.FailureToError(failure.GetCause()))
	} else if failure.GetResetWorkflowFailureInfo() != nil {
		resetWorkflowFailureInfo := failure.GetResetWorkflowFailureInfo()
		lastHeartbeatDetails := newEncodedValues(resetWorkflowFailureInfo.GetLastHeartbeatDetails(), dfc.dataConverter)
		err = NewApplicationError(message, "", true, dfc.FailureToError(failure.GetCause()), lastHeartbeatDetails)
	} else if failure.GetActivityFailureInfo() != nil {
		activityTaskInfoFailure := failure.GetActivityFailureInfo()
		err = NewActivityError(
			activityTaskInfoFailure.GetScheduledEventId(),
			activityTaskInfoFailure.GetStartedEventId(),
			activityTaskInfoFailure.GetIdentity(),
			activityTaskInfoFailure.GetActivityType(),
			activityTaskInfoFailure.GetActivityId(),
			activityTaskInfoFailure.GetRetryState(),
			dfc.FailureToError(failure.GetCause()),
		)
	} else if failure.GetChildWorkflowExecutionFailureInfo() != nil {
		childWorkflowExecutionFailureInfo := failure.GetChildWorkflowExecutionFailureInfo()
		err = NewChildWorkflowExecutionError(
			childWorkflowExecutionFailureInfo.GetNamespace(),
			childWorkflowExecutionFailureInfo.GetWorkflowExecution().GetWorkflowId(),
			childWorkflowExecutionFailureInfo.GetWorkflowExecution().GetRunId(),
			childWorkflowExecutionFailureInfo.GetWorkflowType().GetName(),
			childWorkflowExecutionFailureInfo.GetInitiatedEventId(),
			childWorkflowExecutionFailureInfo.GetStartedEventId(),
			childWorkflowExecutionFailureInfo.GetRetryState(),
			dfc.FailureToError(failure.GetCause()),
		)
	} else if info := failure.GetNexusOperationExecutionFailureInfo(); info != nil {
		token := info.GetOperationToken()
		if token == "" {
			//lint:ignore SA1019 ignore deprecated old operation id
			token = info.GetOperationId()
		}
		err = &NexusOperationError{
			Message:          failure.Message,
			Cause:            dfc.FailureToError(failure.GetCause()),
			Failure:          originalFailure,
			ScheduledEventID: info.GetScheduledEventId(),
			Endpoint:         info.GetEndpoint(),
			Service:          info.GetService(),
			Operation:        info.GetOperation(),
			OperationToken:   token,
		}
	} else if info := failure.GetNexusHandlerFailureInfo(); info != nil {
		var retryBehavior nexus.HandlerErrorRetryBehavior
		switch info.RetryBehavior {
		case enumspb.NEXUS_HANDLER_ERROR_RETRY_BEHAVIOR_RETRYABLE:
			retryBehavior = nexus.HandlerErrorRetryBehaviorRetryable
		case enumspb.NEXUS_HANDLER_ERROR_RETRY_BEHAVIOR_NON_RETRYABLE:
			retryBehavior = nexus.HandlerErrorRetryBehaviorNonRetryable
		}
		// Check if the message is the default message or if it was set by the user. If it's the default message,
		// we will replace it with an empty string to avoid confusion.
		cause := dfc.FailureToError(failure.GetCause())
		typ := nexus.HandlerErrorType(info.Type)
		if strings.HasPrefix(message, fmt.Sprintf("handler error (%s)", typ)) {
			message = ""
		}
		originalFailure, terr := temporalFailureToNexusFailure(failure)
		if terr != nil {
			originalFailure = nil
		}
		err = &nexus.HandlerError{
			Type:            typ,
			Message:         message,
			StackTrace:      stackTrace,
			Cause:           cause,
			RetryBehavior:   retryBehavior,
			OriginalFailure: originalFailure,
		}
	}

	if err == nil {
		// All unknown types are considered to be retryable ApplicationError.
		err = NewApplicationError(message, "", false, dfc.FailureToError(failure.GetCause()))
	}

	if fh, ok := err.(failureHolder); ok {
		fh.setFailure(originalFailure)
	}

	return err
}

package internal

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"go.temporal.io/api/proxy"
	"go.temporal.io/api/serviceerror"
	"go.temporal.io/sdk/internal/common/metrics"
	"go.temporal.io/sdk/internal/common/retry"
	"google.golang.org/grpc"
	"google.golang.org/grpc/backoff"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/credentials"
	"google.golang.org/grpc/credentials/insecure"
	"google.golang.org/grpc/encoding"
	grpcgzip "google.golang.org/grpc/encoding/gzip"
	"google.golang.org/grpc/keepalive"
	"google.golang.org/grpc/metadata"
	"google.golang.org/grpc/status"
	"google.golang.org/protobuf/proto"
)

type (
	// dialParameters are passed to GRPCDialer and must be used to create gRPC connection.
	dialParameters struct {
		HostPort              string
		UserConnectionOptions ConnectionOptions
		RequiredInterceptors  []grpc.UnaryClientInterceptor
		DefaultServiceConfig  string
	}
)

const (
	// LocalHostPort is a default host:port for worker and client to connect to.
	//
	// Exposed as: [go.temporal.io/sdk/client.DefaultHostPort]
	LocalHostPort = "localhost:7233"

	// defaultServiceConfig is a default gRPC connection service config which enables DNS round-robin between IPs.
	defaultServiceConfig = `{"loadBalancingConfig": [{"round_robin":{}}]}`

	// minConnectTimeout is the minimum amount of time we are willing to give a connection to complete.
	minConnectTimeout = 20 * time.Second

	// attemptSuffix is a suffix added to the metric name for individual call attempts made to the server, which includes retries.
	attemptSuffix = "_attempt"

	// mb is a number of bytes in a megabyte
	mb = 1024 * 1024

	// defaultMaxPayloadSize is a maximum size of the payload that grpc client would allow.
	defaultMaxPayloadSize = 128 * mb

	// defaultKeepAliveTime is the keep alive time if one is not specified.
	defaultKeepAliveTime = 30 * time.Second

	// defaultKeepAliveTimeout is the keep alive timeout if one is not specified.
	defaultKeepAliveTimeout = 15 * time.Second

	// temporalNamespaceHeaderKey is the header key that should contain the target namespace of the request.
	temporalNamespaceHeaderKey = "temporal-namespace"
)

func dial(params dialParameters) (*grpc.ClientConn, error) {
	var securityOptions []grpc.DialOption
	if params.UserConnectionOptions.TLS != nil {
		securityOptions = []grpc.DialOption{
			grpc.WithTransportCredentials(credentials.NewTLS(params.UserConnectionOptions.TLS)),
		}
	} else {
		securityOptions = []grpc.DialOption{
			grpc.WithTransportCredentials(insecure.NewCredentials()),
			grpc.WithAuthority(params.UserConnectionOptions.Authority),
		}
	}

	maxPayloadSize := defaultMaxPayloadSize
	if params.UserConnectionOptions.MaxPayloadSize != 0 {
		maxPayloadSize = params.UserConnectionOptions.MaxPayloadSize
	}

	// gRPC maintains connection pool inside grpc.ClientConn.
	// This connection pool has auto reconnect feature.
	// If connection goes down, gRPC will try to reconnect using exponential backoff strategy:
	// https://github.com/grpc/grpc/blob/master/doc/connection-backoff.md.
	// Default MaxDelay is 120 seconds which is too high.
	// Setting it to retryPollOperationMaxInterval here will correlate with poll reconnect interval.
	var cp = grpc.ConnectParams{
		Backoff:           backoff.DefaultConfig,
		MinConnectTimeout: minConnectTimeout,
	}
	cp.Backoff.BaseDelay = retryPollOperationInitialInterval
	cp.Backoff.MaxDelay = retryPollOperationMaxInterval
	opts := []grpc.DialOption{
		grpc.WithChainUnaryInterceptor(params.RequiredInterceptors...),
		grpc.WithDefaultServiceConfig(params.DefaultServiceConfig),
		grpc.WithConnectParams(cp),
	}

	opts = append(opts, securityOptions...)
	opts = append(opts, grpc.WithDefaultCallOptions(grpc.MaxCallSendMsgSize(maxPayloadSize)))
	opts = append(opts, grpc.WithDefaultCallOptions(grpc.MaxCallRecvMsgSize(maxPayloadSize)))

	switch compression := params.UserConnectionOptions.GrpcCompression.(type) {
	case nil, *GrpcCompressionGzip:
		opts = append(opts, grpc.WithDefaultCallOptions(grpc.UseCompressor(grpcgzip.Name)))
	case *GrpcCompressionNone:
	default:
		return nil, fmt.Errorf("unsupported gRPC compression option %T", compression)
	}

	if !params.UserConnectionOptions.DisableKeepAliveCheck {
		// gRPC utilizes keep alive mechanism to detect dead connections in case if server didn't close them
		// gracefully. Client would ping the server periodically and expect replies withing the specified timeout.
		// Learn more by reading https://github.com/grpc/grpc/blob/master/doc/keepalive.md
		keepAliveTime := params.UserConnectionOptions.KeepAliveTime
		if keepAliveTime == 0 {
			keepAliveTime = defaultKeepAliveTime
		}
		keepAliveTimeout := params.UserConnectionOptions.KeepAliveTimeout
		if keepAliveTimeout == 0 {
			keepAliveTimeout = defaultKeepAliveTimeout
		}
		var kap = keepalive.ClientParameters{
			Time:                keepAliveTime,
			Timeout:             keepAliveTimeout,
			PermitWithoutStream: !params.UserConnectionOptions.DisableKeepAlivePermitWithoutStream,
		}
		opts = append(opts, grpc.WithKeepaliveParams(kap))
	}

	// Append any user-supplied options
	opts = append(opts, params.UserConnectionOptions.DialOptions...)

	return grpc.NewClient(params.HostPort, opts...)
}

func requiredInterceptors(
	clientOptions *ClientOptions,
	excludeInternalFromRetry *atomic.Bool,
) []grpc.UnaryClientInterceptor {
	interceptors := []grpc.UnaryClientInterceptor{
		errorInterceptor,
		// Report aggregated metrics for the call, this is done outside of the retry loop.
		metrics.NewGRPCInterceptor(clientOptions.MetricsHandler, "", clientOptions.DisableErrorCodeMetricTags),
		// Retry calls when retry configuration is present in the context.
		retry.NewRetryOptionsInterceptor(excludeInternalFromRetry),
	}
	switch clientOptions.ConnectionOptions.GrpcCompression.(type) {
	case nil, *GrpcCompressionGzip:
		interceptors = append(interceptors, newGzipDowngradeInterceptor())
	}
	interceptors = append(
		interceptors,
		// Prevents retrying grpc message too large errors, while allowing retries of other resource exhausted errors.
		retry.GrpcMessageTooLargeErrorInterceptor,
		// Report metrics for every call made to the server.
		metrics.NewGRPCInterceptor(clientOptions.MetricsHandler, attemptSuffix, clientOptions.DisableErrorCodeMetricTags),
	)
	if clientOptions.HeadersProvider != nil {
		interceptors = append(interceptors, headersProviderInterceptor(clientOptions.HeadersProvider))
	}
	if clientOptions.TrafficController != nil {
		interceptors = append(interceptors, trafficControllerInterceptor(clientOptions.TrafficController))
	}
	// Add credentials interceptor. This is intentionally added after headers
	// provider to overwrite anything set there.
	if clientOptions.Credentials != nil {
		if interceptor := clientOptions.Credentials.gRPCInterceptor(); interceptor != nil {
			interceptors = append(interceptors, interceptor)
		}
	}
	// Add temporal header interceptor (namespace + resource ID)
	interceptors = append(interceptors, temporalHeaderInterceptor())
	return interceptors
}

func newGzipDowngradeInterceptor() grpc.UnaryClientInterceptor {
	var gzipUnsupportedMethods sync.Map
	return func(ctx context.Context, method string, req, reply any, cc *grpc.ClientConn, invoker grpc.UnaryInvoker, opts ...grpc.CallOption) error {
		if _, ok := gzipUnsupportedMethods.Load(method); ok {
			return invoker(ctx, method, req, reply, cc, appendIdentityCompressor(opts)...)
		}

		err := invoker(ctx, method, req, reply, cc, opts...)
		if err == nil {
			return nil
		}
		msg := strings.ToLower(err.Error())
		if status.Code(err) != codes.Unimplemented ||
			(!strings.Contains(msg, "decompress") &&
				!strings.Contains(msg, "grpc-encoding") &&
				!strings.Contains(msg, "compressor")) {
			return err
		}

		gzipUnsupportedMethods.Store(method, struct{}{})
		return invoker(ctx, method, req, reply, cc, appendIdentityCompressor(opts)...)
	}
}

func appendIdentityCompressor(opts []grpc.CallOption) []grpc.CallOption {
	identityOpts := make([]grpc.CallOption, len(opts), len(opts)+1)
	copy(identityOpts, opts)
	return append(identityOpts, grpc.UseCompressor(encoding.Identity))
}

func temporalHeaderInterceptor() grpc.UnaryClientInterceptor {
	return func(ctx context.Context, method string, req, reply any, cc *grpc.ClientConn, invoker grpc.UnaryInvoker, opts ...grpc.CallOption) error {
		var extractOpts proxy.ExtractHeadersOptions
		extractOpts.Request, _ = req.(proto.Message)
		extractOpts.ExistingMetadata, _ = metadata.FromOutgoingContext(ctx)
		if extractOpts.Request != nil {
			if headers, err := proxy.ExtractTemporalRequestHeaders(ctx, extractOpts); err != nil {
				return err
			} else if len(headers) > 0 {
				ctx = metadata.AppendToOutgoingContext(ctx, headers...)
			}
		}
		return invoker(ctx, method, req, reply, cc, opts...)
	}
}

func trafficControllerInterceptor(controller TrafficController) grpc.UnaryClientInterceptor {
	return func(ctx context.Context, method string, req, reply any, cc *grpc.ClientConn, invoker grpc.UnaryInvoker, opts ...grpc.CallOption) error {
		err := controller.CheckCallAllowed(ctx, method, req, reply)
		// Break execution chain and return an error without sending actual request to the server.
		if err != nil {
			return err
		}
		return invoker(ctx, method, req, reply, cc, opts...)
	}
}

func headersProviderInterceptor(headersProvider HeadersProvider) grpc.UnaryClientInterceptor {
	return func(ctx context.Context, method string, req, reply any, cc *grpc.ClientConn, invoker grpc.UnaryInvoker, opts ...grpc.CallOption) error {
		headers, err := headersProvider.GetHeaders(ctx)
		if err != nil {
			return err
		}
		for k, v := range headers {
			ctx = metadata.AppendToOutgoingContext(ctx, k, v)
		}
		return invoker(ctx, method, req, reply, cc, opts...)
	}
}

func errorInterceptor(ctx context.Context, method string, req, reply any, cc *grpc.ClientConn, invoker grpc.UnaryInvoker, opts ...grpc.CallOption) error {
	err := invoker(ctx, method, req, reply, cc, opts...)
	var grpcMessageTooLargeErr *retry.GrpcMessageTooLargeError
	if !errors.As(err, &grpcMessageTooLargeErr) {
		err = serviceerror.FromStatus(status.Convert(err))
	}
	return err
}

package internal

import (
	"context"

	"go.temporal.io/sdk/converter"

	commonpb "go.temporal.io/api/common/v1"
)

// HeaderWriter is an interface to write information to temporal headers
type (
	//
	// Exposed as: [go.temporal.io/sdk/workflow.HeaderWriter]
	HeaderWriter interface {
		Set(string, *commonpb.Payload)
	}

	// HeaderReader is an interface to read information from temporal headers
	//
	// Exposed as: [go.temporal.io/sdk/workflow.HeaderReader]
	HeaderReader interface {
		Get(string) (*commonpb.Payload, bool)
		ForEachKey(handler func(string, *commonpb.Payload) error) error
	}

	// ContextPropagator is an interface that determines what information from
	// context to pass along
	//
	// Exposed as: [go.temporal.io/sdk/workflow.ContextPropagator]
	ContextPropagator interface {
		// Inject injects information from a Go Context into headers
		Inject(context.Context, HeaderWriter) error

		// Extract extracts context information from headers and returns a context
		// object
		Extract(context.Context, HeaderReader) (context.Context, error)

		// InjectFromWorkflow injects information from workflow context into headers
		InjectFromWorkflow(Context, HeaderWriter) error

		// ExtractToWorkflow extracts context information from headers and returns
		// a workflow context
		ExtractToWorkflow(Context, HeaderReader) (Context, error)
	}

	// CodecContextPropagator optionally applies the configured client's payload
	// codec to this propagator's headers. EncodeHeaders defaults to false when
	// this interface is not implemented. When true, Inject methods must return
	// serialized but not codec-encoded payloads. Extract methods receive a
	// privately decoded view; headers supplied by other producers are unchanged.
	//
	// Exposed as: [go.temporal.io/sdk/workflow.CodecContextPropagator]
	CodecContextPropagator interface {
		ContextPropagator
		EncodeHeaders() bool
	}

	// ContextAware is an optional interface that can be implemented alongside
	// DataConverter. This interface allows Temporal to pass Workflow/Activity
	// contexts to the DataConverter so that it may tailor its behavior.
	//
	// Note that data converters may be called in non-context-aware situations to
	// convert payloads that may not be customized per context. Data converter
	// implementers should not expect or require contextual data be present.
	//
	// Exposed as: [go.temporal.io/sdk/workflow.ContextAware]
	ContextAware = converter.ContextAware

	headerReader struct {
		header *commonpb.Header
	}
)

func (hr *headerReader) ForEachKey(handler func(string, *commonpb.Payload) error) error {
	if hr.header == nil {
		return nil
	}
	for key, value := range hr.header.Fields {
		if err := handler(key, value); err != nil {
			return err
		}
	}
	return nil
}

func (hr *headerReader) Get(key string) (*commonpb.Payload, bool) {
	if hr.header == nil {
		return nil, false
	}
	payload, ok := hr.header.Fields[key]
	return payload, ok
}

// NewHeaderReader returns a header reader interface
func NewHeaderReader(header *commonpb.Header) HeaderReader {
	return &headerReader{header: header}
}

type headerWriter struct {
	header      *commonpb.Header
	codecValues map[string]*commonpb.Payload
	encode      bool
}

func (hw *headerWriter) Set(key string, value *commonpb.Payload) {
	if hw.header == nil {
		return
	}
	hw.header.Fields[key] = value
	if hw.codecValues != nil {
		delete(hw.codecValues, key)
		if hw.encode {
			hw.codecValues[key] = value
		}
	}
}

// NewHeaderWriter returns a header writer interface
func NewHeaderWriter(header *commonpb.Header) HeaderWriter {
	if header != nil && header.Fields == nil {
		header.Fields = make(map[string]*commonpb.Payload)
	}
	return &headerWriter{header: header}
}

// WithWorkflowContext returns a new DataConverter tailored to the passed Workflow context if
// the DataConverter implements the ContextAware interface. Otherwise the DataConverter is returned
// as-is.
func WithWorkflowContext(ctx Context, dc converter.DataConverter) converter.DataConverter {
	if d, ok := dc.(ContextAware); ok {
		return d.WithWorkflowContext(ctx)
	}
	return dc
}

// WithContext returns a new DataConverter tailored to the passed Workflow/Activity context if
// the DataConverter implements the ContextAware interface. Otherwise the DataConverter is returned
// as-is. This is generally used for Activity context but can be context for a Workflow if we're
// not yet executing the workflow so do not have a workflow.Context.
func WithContext(ctx context.Context, dc converter.DataConverter) converter.DataConverter {
	if d, ok := dc.(ContextAware); ok {
		return d.WithContext(ctx)
	}
	return dc
}

