package internal

// eagerWorker is the minimal worker interface needed for eager activities and workflows
type eagerWorker interface {
	// tryReserveSlot tries to reserver a task slot on the worker without blocking
	// caller is expected to release the slot with releaseSlot
	tryReserveSlot() *SlotPermit
	// releaseSlot release a task slot acquired by tryReserveSlot
	releaseSlot(permit *SlotPermit, reason SlotReleaseReason)
	// pushEagerTask pushes a new eager workflow task to the workers task queue.
	// should only be called with a reserved slot.
	pushEagerTask(task eagerTask)
	// getDeploymentOptions returns the worker's deployment options
	getDeploymentOptions() WorkerDeploymentOptions
}

package internal

import (
	"fmt"
	"sync"

	"go.temporal.io/api/workflowservice/v1"
	"go.temporal.io/sdk/internal/common/metrics"
)

// eagerActivityExecutor is a worker-scoped executor for eager activities that
// are returned from workflow task completion responses.
type eagerActivityExecutor struct {
	eagerActivityExecutorOptions

	activityWorker eagerWorker
	heldSlotCount  int
	countLock      sync.Mutex
}

type eagerActivityExecutorOptions struct {
	disabled       bool
	taskQueue      string
	metricsHandler metrics.Handler
	// If 0, there is no maximum
	maxConcurrent int
	maxPerTask    int
}

// newEagerActivityExecutor creates a new worker-scoped executor without an
// activityWorker set. The activityWorker must be set on the responding executor
// before it will be able to execute activities.
func newEagerActivityExecutor(options eagerActivityExecutorOptions) *eagerActivityExecutor {
	if options.maxPerTask <= 0 {
		panic("maxPerTask must be positive")
	}
	if options.metricsHandler == nil {
		options.metricsHandler = metrics.NopHandler
	}
	return &eagerActivityExecutor{eagerActivityExecutorOptions: options}
}

func (e *eagerActivityExecutor) applyToRequest(
	req *workflowservice.RespondWorkflowTaskCompletedRequest,
) []*SlotPermit {
	reservedPermits := make([]*SlotPermit, 0)

	// Go over every command checking for activities that can be eagerly executed
	eagerRequestsThisTask := 0
	for _, command := range req.Commands {
		if attrs := command.GetScheduleActivityTaskCommandAttributes(); attrs != nil {
			// If not present, disabled, not requested, no activity worker, on a
			// different task queue, or reached max for task, we must mark as
			// explicitly disabled
			eagerDisallowed := e == nil ||
				e.disabled ||
				!attrs.RequestEagerExecution ||
				e.activityWorker == nil ||
				e.taskQueue != attrs.TaskQueue.GetName() ||
				eagerRequestsThisTask >= e.maxPerTask
			if eagerDisallowed {
				attrs.RequestEagerExecution = false
			} else {
				// If it has been requested, attempt to reserve one pending
				maybePermit := e.reserveOnePendingSlot()
				if maybePermit != nil {
					reservedPermits = append(reservedPermits, maybePermit)
					attrs.RequestEagerExecution = true
					eagerRequestsThisTask++
				} else {
					attrs.RequestEagerExecution = false
				}
			}
		}
	}
	return reservedPermits
}

func (e *eagerActivityExecutor) reserveOnePendingSlot() *SlotPermit {
	// Confirm that, if we have a max, issued count isn't already there
	e.countLock.Lock()
	defer e.countLock.Unlock()
	// Confirm that, if we have a max, held count isn't already there
	if e.maxConcurrent > 0 && e.heldSlotCount >= e.maxConcurrent {
		// No more room
		return nil
	}
	// Reserve a spot for our request via a non-blocking attempt
	maybePermit := e.activityWorker.tryReserveSlot()
	if maybePermit != nil {
		// Ensure that on release we decrement the held count
		maybePermit.extraReleaseCallback = func() {
			e.countLock.Lock()
			defer e.countLock.Unlock()
			e.heldSlotCount--
		}
		e.heldSlotCount++
	}
	return maybePermit
}

func (e *eagerActivityExecutor) handleResponse(
	resp *workflowservice.RespondWorkflowTaskCompletedResponse,
	reservedPermits []*SlotPermit,
) {
	// Ignore disabled or none present
	amountSlotsReserved := len(reservedPermits)
	if e == nil || e.activityWorker == nil || e.disabled ||
		(len(resp.GetActivityTasks()) == 0 && amountSlotsReserved == 0) {
		return
	} else if len(resp.GetActivityTasks()) > amountSlotsReserved {
		panic(fmt.Sprintf("Unexpectedly received %v eager activities though we only requested %v",
			len(resp.GetActivityTasks()), amountSlotsReserved))
	}

	// Give back unfulfilled slots and record for later use
	unfulfilledSlots := amountSlotsReserved - len(resp.GetActivityTasks())
	// Release unneeded permits
	for range unfulfilledSlots {
		unneededPermit := reservedPermits[len(reservedPermits)-1]
		reservedPermits = reservedPermits[:len(reservedPermits)-1]
		e.activityWorker.releaseSlot(unneededPermit, SlotReleaseReasonUnused)
	}

	// Start each activity asynchronously
	for i, activity := range resp.GetActivityTasks() {
		// Match polling: record receipt even if shutdown prevents execution.
		metricsHandler := e.metricsHandler.WithTags(metrics.ActivityTags(
			activity.WorkflowType.GetName(), activity.ActivityType.GetName(), e.taskQueue))
		scheduleToStartLatency := activity.GetStartedTime().AsTime().Sub(activity.GetCurrentAttemptScheduledTime().AsTime())
		metricsHandler.Timer(metrics.ActivityScheduleToStartLatency).Record(scheduleToStartLatency)

		// Asynchronously execute
		e.activityWorker.pushEagerTask(
			eagerTask{
				task:   &activityTask{task: activity, permit: reservedPermits[i]},
				permit: reservedPermits[i],
			})
	}
}

package internal

import (
	"math/rand"
	"sync"
	"sync/atomic"

	"go.temporal.io/api/deployment/v1"
	"go.temporal.io/api/enums/v1"
	"go.temporal.io/api/workflowservice/v1"
)

// eagerWorkflowDispatcher is responsible for finding an available worker for an eager workflow task.
type eagerWorkflowDispatcher struct {
	lock               sync.RWMutex
	workersByTaskQueue map[string]map[eagerWorker]struct{}
}

// registerWorker registers a worker that can be used for eager workflow dispatch
func (e *eagerWorkflowDispatcher) registerWorker(worker *workflowWorker) {
	e.lock.Lock()
	defer e.lock.Unlock()
	taskQueue := worker.executionParameters.TaskQueue
	if e.workersByTaskQueue[taskQueue] == nil {
		e.workersByTaskQueue[taskQueue] = make(map[eagerWorker]struct{})
	}
	e.workersByTaskQueue[taskQueue][worker.worker] = struct{}{}
}

// deregisterWorker deregister a worker so that it will not be used for eager workflow dispatch
func (e *eagerWorkflowDispatcher) deregisterWorker(worker *workflowWorker) {
	e.lock.Lock()
	defer e.lock.Unlock()
	delete(e.workersByTaskQueue[worker.executionParameters.TaskQueue], worker.worker)
}

// applyToRequest updates request if eager workflow dispatch is possible and returns the eagerWorkflowExecutor to use
func (e *eagerWorkflowDispatcher) applyToRequest(request *workflowservice.StartWorkflowExecutionRequest) *eagerWorkflowExecutor {
	// Try every worker that is assigned to the desired task queue.
	e.lock.RLock()
	workers := e.workersByTaskQueue[request.GetTaskQueue().Name]
	randWorkers := make([]eagerWorker, 0, len(workers))
	// Copy the workers so we can release the lock.
	for worker := range workers {
		randWorkers = append(randWorkers, worker)
	}
	e.lock.RUnlock()
	rand.Shuffle(len(randWorkers), func(i, j int) { randWorkers[i], randWorkers[j] = randWorkers[j], randWorkers[i] })
	for _, worker := range randWorkers {
		maybePermit := worker.tryReserveSlot()
		if maybePermit != nil {
			request.RequestEagerExecution = true
			// Attach deployment options if worker has deployment versioning enabled
			deploymentOpts := worker.getDeploymentOptions()
			if (deploymentOpts.Version != WorkerDeploymentVersion{}) {
				wvMode := enums.WORKER_VERSIONING_MODE_UNVERSIONED
				if deploymentOpts.UseVersioning {
					wvMode = enums.WORKER_VERSIONING_MODE_VERSIONED
				}
				request.EagerWorkerDeploymentOptions = &deployment.WorkerDeploymentOptions{
					DeploymentName:       deploymentOpts.Version.DeploymentName,
					BuildId:              deploymentOpts.Version.BuildID,
					WorkerVersioningMode: wvMode,
				}
			}
			return &eagerWorkflowExecutor{
				worker: worker,
				permit: maybePermit,
			}
		}
	}
	return nil
}

// eagerWorkflowExecutor is a worker-scoped executor for an eager workflow task.
type eagerWorkflowExecutor struct {
	handledResponse atomic.Bool
	worker          eagerWorker
	permit          *SlotPermit
}

// handleResponse of an eager workflow task from a StartWorkflowExecution request.
func (e *eagerWorkflowExecutor) handleResponse(response *workflowservice.PollWorkflowTaskQueueResponse) {
	if !e.handledResponse.CompareAndSwap(false, true) {
		panic("eagerWorkflowExecutor trying to handle multiple responses")
	}
	// Asynchronously execute the task
	e.worker.pushEagerTask(
		eagerTask{
			task: &eagerWorkflowTask{
				task: response,
			},
			permit: e.permit,
		})
}

// releaseUnused should be called if the executor cannot be used because no eager task was received.
// It will error if handleResponse was already called, as this would indicate misuse.
func (e *eagerWorkflowExecutor) releaseUnused() {
	if e.handledResponse.CompareAndSwap(false, true) {
		e.worker.releaseSlot(e.permit, SlotReleaseReasonUnused)
	} else {
		panic("trying to release an eagerWorkflowExecutor that was used")
	}
}

