// errNexusTaskTimeout is returned when the Nexus task handler times out.
// It is used instead of context.DeadlineExceeded to allow the poller to differentiate between Nexus task handler
// timeout and other errors.
var errNexusTaskTimeout = errors.New("nexus task timeout")

// debugDisableTemporalFailureResponses is an internal debug switch to force the SDK
// to treat GetTemporalFailureResponses() as always returning false.
// This is only intended for testing purposes.
var debugDisableTemporalFailureResponses atomic.Bool

// SetDebugDisableTemporalFailureResponses sets the internal debug flag to disable
// temporal failure response support. This forces the SDK to use legacy error handling.
// This is only intended for testing purposes.
func SetDebugDisableTemporalFailureResponses(disable bool) {
	debugDisableTemporalFailureResponses.Store(disable)
}

// getEffectiveTemporalFailureResponses returns the effective value of the
// TemporalFailureResponses capability, taking into account any debug overrides.
func getEffectiveTemporalFailureResponses(serverValue bool) bool {
	if debugDisableTemporalFailureResponses.Load() {
		return false
	}
	return serverValue
}

type nexusTaskHandler struct {
	nexusHandler     nexus.Handler
	identity         string
	namespace        string
	taskQueueName    string
	client           Client
	dataConverter    converter.DataConverter
	failureConverter converter.FailureConverter
	logger           log.Logger
	metricsHandler   metrics.Handler
	registry         *registry
}

func newNexusTaskHandler(
	nexusHandler nexus.Handler,
	identity string,
	namespace string,
	taskQueueName string,
	client Client,
	dataConverter converter.DataConverter,
	failureConverter converter.FailureConverter,
	logger log.Logger,
	metricsHandler metrics.Handler,
	registry *registry,
) *nexusTaskHandler {
	return &nexusTaskHandler{
		nexusHandler:     nexusHandler,
		logger:           logger,
		dataConverter:    dataConverter,
		failureConverter: failureConverter,
		identity:         identity,
		namespace:        namespace,
		taskQueueName:    taskQueueName,
		client:           client,
		metricsHandler:   metricsHandler,
		registry:         registry,
	}
}

func (h *nexusTaskHandler) Execute(task *workflowservice.PollNexusTaskQueueResponse) (*workflowservice.RespondNexusTaskCompletedRequest, *workflowservice.RespondNexusTaskFailedRequest, error) {
	failureReasonSupport := getEffectiveTemporalFailureResponses(task.GetRequest().GetCapabilities().GetTemporalFailureResponses())
	pollerGroupID := task.GetPollerGroupId()
	nctx, handlerErr := h.newNexusOperationContext(task)
	if handlerErr != nil {
		failureRequest, err := h.fillInFailure(
			task.TaskToken,
			handlerErr,
			failureReasonSupport,
			h.failureConverter,
			pollerGroupID,
		)
		if err != nil {
			return nil, nil, err
		}
		return nil, failureRequest, nil
	}
	failureConverter := converter.WithFailureConverterSerializationContext(
		h.failureConverter,
		nctx.nexusSerializationContext,
	)
	res, handlerErr, err := h.execute(nctx, task)
	if err != nil {
		return nil, nil, err
	}
	if handlerErr != nil {
		failureRequest, err := h.fillInFailure(
			task.TaskToken,
			handlerErr,
			failureReasonSupport,
			failureConverter,
			pollerGroupID,
		)
		if err != nil {
			return nil, nil, err
		}
		return nil, failureRequest, nil
	}
	completedRequest, err := h.fillInCompletion(task.TaskToken, res, failureReasonSupport, pollerGroupID)
	if err != nil {
		return nil, nil, err
	}
	return completedRequest, nil, nil
}

func (h *nexusTaskHandler) ExecuteContext(nctx *NexusOperationContext, task *workflowservice.PollNexusTaskQueueResponse) (*workflowservice.RespondNexusTaskCompletedRequest, *workflowservice.RespondNexusTaskFailedRequest, error) {
	failureReasonSupport := getEffectiveTemporalFailureResponses(task.GetRequest().GetCapabilities().GetTemporalFailureResponses())
	failureConverter := converter.WithFailureConverterSerializationContext(
		h.failureConverter,
		nctx.nexusSerializationContext,
	)
	pollerGroupID := task.GetPollerGroupId()
	res, handlerErr, err := h.execute(nctx, task)
	if err != nil {
		return nil, nil, err
	}
	if handlerErr != nil {
		failureRequest, err := h.fillInFailure(
			task.TaskToken,
			handlerErr,
			failureReasonSupport,
			failureConverter,
			pollerGroupID,
		)
		if err != nil {
			return nil, nil, err
		}
		return nil, failureRequest, nil
	}
	completedRequest, err := h.fillInCompletion(task.TaskToken, res, failureReasonSupport, pollerGroupID)
	if err != nil {
		return nil, nil, err
	}
	return completedRequest, nil, nil
}

func (h *nexusTaskHandler) execute(nctx *NexusOperationContext, task *workflowservice.PollNexusTaskQueueResponse) (*nexuspb.Response, *nexus.HandlerError, error) {
	header := nexus.Header(task.GetRequest().GetHeader())
	if header == nil {
		header = nexus.Header{}
	}

	ctx, cancel, handlerErr := h.goContextForTask(nctx, header)
	if handlerErr != nil {
		return nil, handlerErr, nil
	}
	defer cancel()

	switch req := task.GetRequest().GetVariant().(type) {
	case *nexuspb.Request_StartOperation:
		return h.handleStartOperation(ctx, nctx, req.StartOperation, header)
	case *nexuspb.Request_CancelOperation:
		return h.handleCancelOperation(ctx, nctx, req.CancelOperation, header)
	default:
		return nil, nexus.NewHandlerErrorf(
			nexus.HandlerErrorTypeNotImplemented,
			"unknown request type",
		), nil
	}
}

func (h *nexusTaskHandler) handleStartOperation(
	ctx context.Context,
	nctx *NexusOperationContext,
	req *nexuspb.StartOperationRequest,
	header nexus.Header,
) (*nexuspb.Response, *nexus.HandlerError, error) {
	var dataConverter converter.DataConverter
	if nctx.Endpoint == systemNexusEndpoint {
		// In production, System Nexus operations are handled by the temporal service.
		// This path is only exercised by unit tests with a mock system nexus handler.
		dataConverter = converter.NewCompositeDataConverter(converter.NewProtoPayloadConverter())
	} else {
		dataConverter = converter.WithDataConverterSerializationContext(
			h.dataConverter,
			nctx.nexusSerializationContext,
		)
	}
	failureConverter := converter.WithFailureConverterSerializationContext(
		h.failureConverter,
		nctx.nexusSerializationContext,
	)
	serializer := &payloadSerializer{
		converter: dataConverter,
		payload:   req.GetPayload(),
	}
	// Create a fake lazy value, Temporal server already converts Nexus content into payloads.
	input := nexus.NewLazyValue(
		serializer,
		&nexus.Reader{
			ReadCloser: emptyReaderNopCloser,
		},
	)
	// Ensure we don't pass nil values to handlers.
	callbackHeader := req.GetCallbackHeader()
	if callbackHeader == nil {
		callbackHeader = make(map[string]string)
	}
	nexusLinks := make([]nexus.Link, 0, len(req.GetLinks()))
	// requestLinks holds the inbound links in common.v1.Link form so the RPCs the handler
	// issues (e.g. signal, signalWithStart) can attach them to their request's links field, linking
	// the callee's history events back to the caller.
	var requestLinks []*common.Link
	for _, link := range req.GetLinks() {
		if link == nil {
			continue
		}
		linkURL, err := url.Parse(link.GetUrl())
		if err != nil {
			nctx.log.Error("Failed to parse link url", tagLinkURL, link.GetUrl(), tagError, err)
			return nil, nexus.NewHandlerErrorf(nexus.HandlerErrorTypeBadRequest, "failed to parse link url"), nil
		}
		nexusLinks = append(nexusLinks, nexus.Link{
			URL:  linkURL,
			Type: link.GetType(),
		})
		if commonLink, ok := apinexus.NexusLinkToCommonLink(link); ok {
			requestLinks = append(requestLinks, commonLink)
		}
	}
	if len(requestLinks) > 0 {
		ctx = context.WithValue(ctx, NexusOperationRequestLinksKey, requestLinks)
	}
	// Handle old servers that may not send a request ID. Generate one if missing.
	requestID := req.RequestId
	if requestID == "" {
		requestID = uuid.NewString()
	}
	nctx.RequestID = requestID
	startOptions := nexus.StartOperationOptions{
		RequestID:      requestID,
		CallbackURL:    req.Callback,
		Header:         header,
		CallbackHeader: callbackHeader,
		Links:          nexusLinks,
	}
	ctx = nexus.WithHandlerContext(ctx, nexus.HandlerInfo{
		Service:   req.GetService(),
		Operation: req.GetOperation(),
		Header:    header,
	})
	var opres nexus.HandlerStartOperationResult[any]
	var err error
	var panic bool
	func() {
		defer func() {
			recovered := recover()
			if recovered != nil {
				panic = true
				var ok bool
				err, ok = recovered.(error)
				if !ok {
					err = fmt.Errorf("panic: %v", recovered)
				}

				nctx.log.Error("Panic captured while handling Nexus task", tagStackTrace, string(debug.Stack()), tagError, err)
			}
		}()
		opres, err = h.nexusHandler.StartOperation(ctx, req.GetService(), req.GetOperation(), input, startOptions)
	}()
	if ctx.Err() != nil {
		if !panic {
			nctx.log.Error("Context error while processing Nexus task", tagError, ctx.Err())
		}
		return nil, nil, errNexusTaskTimeout
	}
	if err != nil {
		if !panic {
			nctx.log.Error("Handler returned error while processing Nexus task", tagError, err)
		}
		var unsuccessfulOperationErr *nexus.OperationError
		err = convertKnownErrors(err)
		if errors.As(err, &unsuccessfulOperationErr) {
			// Convert OperationError to a Temporal failure
			var tempoErr error
			switch unsuccessfulOperationErr.State {
			case nexus.OperationStateCanceled:
				tempoErr = NewCanceledErrorWithOptions(CanceledErrorOptions{
					Message: unsuccessfulOperationErr.Message,
					Cause:   unsuccessfulOperationErr.Cause,
				})
			case nexus.OperationStateFailed:
				tempoErr = NewApplicationErrorWithOptions(
					unsuccessfulOperationErr.Message,
					"OperationError",
					ApplicationErrorOptions{
						NonRetryable: true,
						Cause:        unsuccessfulOperationErr.Cause,
					},
				)
			default:
				return nil, nexus.NewHandlerErrorf(
					nexus.HandlerErrorTypeInternal,
					"handler returned an invalid operation error type: %s",
					unsuccessfulOperationErr.State,
				), nil
			}
			return &nexuspb.Response{
				Variant: &nexuspb.Response_StartOperation{
					StartOperation: &nexuspb.StartOperationResponse{
						Variant: &nexuspb.StartOperationResponse_Failure{
							Failure: failureConverter.ErrorToFailure(tempoErr),
						},
					},
				},
			}, nil, nil
		}
		var handlerErr *nexus.HandlerError
		if errors.As(err, &handlerErr) {
			return nil, handlerErr, nil
		}
		// Default to internal error.
		return nil, &nexus.HandlerError{
			Type:    nexus.HandlerErrorTypeInternal,
			Message: "internal handler error",
			Cause:   err,
		}, nil
	}
	switch t := opres.(type) {
	case *nexus.HandlerStartOperationResultAsync:
		nexusLinks := nexus.HandlerLinks(ctx)
		links := make([]*nexuspb.Link, len(nexusLinks))
		for i, nexusLink := range nexusLinks {
			links[i] = &nexuspb.Link{
				Url:  nexusLink.URL.String(),
				Type: nexusLink.Type,
			}
		}
		links = append(links, h.responseLinks(nctx)...)
		token := t.OperationToken
		return &nexuspb.Response{
			Variant: &nexuspb.Response_StartOperation{
				StartOperation: &nexuspb.StartOperationResponse{
					Variant: &nexuspb.StartOperationResponse_AsyncSuccess{
						AsyncSuccess: &nexuspb.StartOperationResponse_Async{
							OperationToken: token,
							Links:          links,
						},
					},
				},
			},
		}, nil, nil
	default:
		nexusLinks := nexus.HandlerLinks(ctx)
		links := make([]*nexuspb.Link, len(nexusLinks))
		for i, nexusLink := range nexusLinks {
			links[i] = &nexuspb.Link{
				Url:  nexusLink.URL.String(),
				Type: nexusLink.Type,
			}
		}
		links = append(links, h.responseLinks(nctx)...)
		// *nexus.HandlerStartOperationResultSync is generic, we can't type switch unfortunately.
		value := reflect.ValueOf(t).Elem().FieldByName("Value").Interface()
		payload, err := dataConverter.ToPayload(value)
		if err != nil {
			nctx.log.Error("Cannot convert Nexus sync result", tagError, err)
			return nil, nexus.NewHandlerErrorf(
				nexus.HandlerErrorTypeInternal,
				"cannot convert nexus sync result: %v", err,
			), nil
		}
		return &nexuspb.Response{
			Variant: &nexuspb.Response_StartOperation{
				StartOperation: &nexuspb.StartOperationResponse{
					Variant: &nexuspb.StartOperationResponse_SyncSuccess{
						SyncSuccess: &nexuspb.StartOperationResponse_Sync{
							Payload: payload,
							Links:   links,
						},
					},
				},
			},
		}, nil, nil
	}
}

// responseLinks converts the response links accumulated on the operation context (from outbound RPCs
// the handler issued, such as signal or signalWithStart) into nexus.v1.Links to attach to the
// StartOperationResponse. Unsupported variants are skipped.
func (h *nexusTaskHandler) responseLinks(nctx *NexusOperationContext) []*nexuspb.Link {
	responseLinks := nctx.ResponseLinks()
	if len(responseLinks) == 0 {
		return nil
	}
	out := make([]*nexuspb.Link, 0, len(responseLinks))
	for _, responseLink := range responseLinks {
		if nexusLink, ok := apinexus.CommonLinkToNexusLink(responseLink); ok {
			out = append(out, nexusLink)
		}
	}
	return out
}

func (h *nexusTaskHandler) handleCancelOperation(ctx context.Context, nctx *NexusOperationContext, req *nexuspb.CancelOperationRequest, header nexus.Header) (*nexuspb.Response, *nexus.HandlerError, error) {
	cancelOptions := nexus.CancelOperationOptions{Header: header}
	ctx = nexus.WithHandlerContext(ctx, nexus.HandlerInfo{
		Service:   req.GetService(),
		Operation: req.GetOperation(),
		Header:    header,
	})
	var err error
	var panic bool
	func() {
		defer func() {
			recovered := recover()
			if recovered != nil {
				panic = true
				var ok bool
				err, ok = recovered.(error)
				if !ok {
					err = fmt.Errorf("panic: %v", recovered)
				}

				nctx.log.Error("Panic captured while handling Nexus task", tagStackTrace, string(debug.Stack()), tagError, err)
			}
		}()
		token := req.GetOperationToken()
		if token == "" {
			// Support servers older than 1.27.0.
			//lint:ignore SA1019 ignore deprecated
			token = req.GetOperationId()
		}
		err = h.nexusHandler.CancelOperation(ctx, req.GetService(), req.GetOperation(), token, cancelOptions)
	}()
	if ctx.Err() != nil {
		if !panic {
			nctx.log.Error("Context error while processing Nexus task", tagError, ctx.Err())
		}
		return nil, nil, errNexusTaskTimeout
	}
	if err != nil {
		if !panic {
			nctx.log.Error("Handler returned error while processing Nexus task", tagError, err)
		}
		err = convertKnownErrors(err)
		var handlerErr *nexus.HandlerError
		if errors.As(err, &handlerErr) {
			return nil, handlerErr, nil
		}
		// Default to internal error.
		return nil, &nexus.HandlerError{
			Type:    nexus.HandlerErrorTypeInternal,
			Message: "internal handler error",
			Cause:   err,
		}, nil
	}

	return &nexuspb.Response{
		Variant: &nexuspb.Response_CancelOperation{
			CancelOperation: &nexuspb.CancelOperationResponse{},
		},
	}, nil, nil
}

func (h *nexusTaskHandler) goContextForTask(nctx *NexusOperationContext, header nexus.Header) (context.Context, context.CancelFunc, *nexus.HandlerError) {
	// Associate the NexusOperationContext with the context.Context used to invoke operations.
	ctx := context.WithValue(context.Background(), nexusOperationContextKey, nctx)

	timeoutStr := header.Get(nexus.HeaderRequestTimeout)
	if timeoutStr != "" {
		timeout, err := time.ParseDuration(timeoutStr)
		if err != nil {
			return nil, nil, nexus.NewHandlerErrorf(nexus.HandlerErrorTypeBadRequest, "cannot parse request timeout")
		}

		ctx, cancel := context.WithTimeout(ctx, timeout)
		return ctx, cancel, nil
	}

	return ctx, func() {}, nil
}

func (h *nexusTaskHandler) newNexusOperationContext(response *workflowservice.PollNexusTaskQueueResponse) (*NexusOperationContext, *nexus.HandlerError) {
	var service, operation string

	switch req := response.GetRequest().GetVariant().(type) {
	case *nexuspb.Request_StartOperation:
		service = req.StartOperation.Service
		operation = req.StartOperation.Operation
	case *nexuspb.Request_CancelOperation:
		service = req.CancelOperation.Service
		operation = req.CancelOperation.Operation
	default:
		return nil, nexus.NewHandlerErrorf(nexus.HandlerErrorTypeNotImplemented, "unknown request type")
	}

	logger := log.With(h.logger,
		tagNexusService, service,
		tagNexusOperation, operation,
		tagTaskQueue, h.taskQueueName,
	)
	metricsHandler := h.metricsHandler.WithTags(metrics.NexusTags(service, operation, h.taskQueueName))

	return &NexusOperationContext{
		client:    h.client,
		Endpoint:  response.GetRequest().GetEndpoint(),
		Namespace: h.namespace,
		TaskQueue: h.taskQueueName,
		nexusSerializationContext: converter.NexusSerializationContext{
			Endpoint:  response.GetRequest().GetEndpoint(),
			Service:   service,
			Operation: operation,
		},
		metricsHandler: metricsHandler,
		log:            logger,
		registry:       h.registry,
	}, nil
}

func (h *nexusTaskHandler) fillInCompletion(taskToken []byte, res *nexuspb.Response, failureReasonSupport bool, pollerGroupID string) (*workflowservice.RespondNexusTaskCompletedRequest, error) {
	// Handle conversion of Failure to OperationError for backwards compatibility with old servers.
	if res.GetStartOperation().GetFailure() != nil && !failureReasonSupport {
		// Convert to operation error for backwards compatibility.
		f := res.GetStartOperation().GetFailure()
		var state string
		if cf := f.GetCanceledFailureInfo(); cf != nil {
			state = string(nexus.OperationStateCanceled)
		} else if af := f.GetApplicationFailureInfo(); af != nil {
			state = string(nexus.OperationStateFailed)
		} else {
			return nil, fmt.Errorf("cannot convert failure to operation error without failure reason support")
		}
		failure, err := h.temporalFailureToNexusFailure(f.GetCause())
		if err != nil {
			return nil, err
		}
		res.Variant = &nexuspb.Response_StartOperation{
			StartOperation: &nexuspb.StartOperationResponse{
				Variant: &nexuspb.StartOperationResponse_OperationError{
					//lint:ignore SA1019 servers without Temporal failure responses require the legacy operation error variant
					OperationError: &nexuspb.UnsuccessfulOperationError{
						OperationState: state,
						Failure:        failure,
					},
				},
			},
		}
	}
	return &workflowservice.RespondNexusTaskCompletedRequest{
		Identity:      h.identity,
		Namespace:     h.namespace,
		TaskToken:     taskToken,
		Response:      res,
		PollerGroupId: pollerGroupID,
	}, nil
}

func (h *nexusTaskHandler) fillInFailure(
	taskToken []byte,
	handlerError *nexus.HandlerError,
	failureReasonSupport bool,
	failureConverter converter.FailureConverter,
	pollerGroupID string,
) (*workflowservice.RespondNexusTaskFailedRequest, error) {
	r := &workflowservice.RespondNexusTaskFailedRequest{
		Identity:      h.identity,
		Namespace:     h.namespace,
		TaskToken:     taskToken,
		PollerGroupId: pollerGroupID,
	}
	if failureReasonSupport {
		r.Failure = failureConverter.ErrorToFailure(handlerError)
	} else {
		he, err := h.nexusHandlerErrorToProto(handlerError, failureConverter)
		if err != nil {
			return nil, err
		}
		//lint:ignore SA1019 ignore deprecated
		r.Error = he
	}
	return r, nil
}

var nexusFailureTypeString = string((&failurepb.Failure{}).ProtoReflect().Descriptor().FullName())
var nexusFailureMetadata = map[string]string{"type": nexusFailureTypeString}

func (h *nexusTaskHandler) errorToFailure(err error, failureConverter converter.FailureConverter) (*nexuspb.Failure, error) {
	failure := failureConverter.ErrorToFailure(err)
	if failure == nil {
		return nil, nil
	}

	message := failure.Message
	failure.Message = ""
	b, err := protojson.Marshal(failure)
	if err != nil {
		return nil, err
	}
	return &nexuspb.Failure{
		Message:  message,
		Metadata: nexusFailureMetadata,
		Details:  b,
	}, nil
}

func (h *nexusTaskHandler) temporalFailureToNexusFailure(failure *failurepb.Failure) (*nexuspb.Failure, error) {
	if failure == nil {
		return nil, nil
	}
	message := failure.Message
	failure.Message = ""
	b, err := protojson.Marshal(failure)
	if err != nil {
		return nil, err
	}
	return &nexuspb.Failure{
		Message:  message,
		Metadata: nexusFailureMetadata,
		Details:  b,
	}, nil
}

func (h *nexusTaskHandler) nexusHandlerErrorToProto(
	handlerErr *nexus.HandlerError,
	failureConverter converter.FailureConverter,
) (*nexuspb.HandlerError, error) {
	failure, err := h.errorToFailure(handlerErr.Cause, failureConverter)
	if err != nil {
		return nil, err
	}
	var retryBehavior enumspb.NexusHandlerErrorRetryBehavior
	switch handlerErr.RetryBehavior {
	case nexus.HandlerErrorRetryBehaviorRetryable:
		retryBehavior = enumspb.NEXUS_HANDLER_ERROR_RETRY_BEHAVIOR_RETRYABLE
	case nexus.HandlerErrorRetryBehaviorNonRetryable:
		retryBehavior = enumspb.NEXUS_HANDLER_ERROR_RETRY_BEHAVIOR_NON_RETRYABLE
	}
	return &nexuspb.HandlerError{
		ErrorType:     string(handlerErr.Type),
		Failure:       failure,
		RetryBehavior: retryBehavior,
	}, nil
}

// payloadSerializer is a fake nexus Serializer that uses a data converter to read from an embedded payload instead of
// using the given nexus.Context. Supports only Deserialize.
type payloadSerializer struct {
	converter converter.DataConverter
	payload   *common.Payload
}

func (p *payloadSerializer) Deserialize(_ *nexus.Content, v any) error {
	err := p.converter.FromPayload(p.payload, v)
	if err == nil {
		return nil
	}
	// The Nexus SDK propagates serializer errors as-is, so errors that already carry an intent for the caller are
	// passed through and converted by the regular error handling path. Anything else means the input could not be
	// read and is reported as a bad request.
	// Not using errors.As to be consistent ApplicationError checking with the rest of the SDK.
	if appErr, ok := err.(*ApplicationError); ok {
		// A non-retryable payload validation error means the input itself is invalid, which is a bad request rather
		// than a handler failure.
		if appErr.NonRetryable() && appErr.Type() == payloadValidationErrorType {
			return &nexus.HandlerError{
				Type:    nexus.HandlerErrorTypeBadRequest,
				Message: "invalid operation input",
				Cause:   err,
			}
		}
		return err
	}
	var handlerErr *nexus.HandlerError
	if errors.As(err, &handlerErr) {
		return err
	}
	return &nexus.HandlerError{
		Type:    nexus.HandlerErrorTypeBadRequest,
		Message: "cannot deserialize operation input",
		Cause:   err,
	}
}

func (p *payloadSerializer) Serialize(v any) (*nexus.Content, error) {
	panic("unimplemented") // not used - operation outputs are directly serialized to payload.
}

var emptyReaderNopCloser = io.NopCloser(bytes.NewReader([]byte{}))

// convertKnownErrors converts known errors to corresponding Nexus HandlerError.
func convertKnownErrors(err error) error {
	// Not using errors.As to be consistent ApplicationError checking with the rest of the SDK.
	if appErr, ok := err.(*ApplicationError); ok && appErr.NonRetryable() {
		return &nexus.HandlerError{
			Type:          nexus.HandlerErrorTypeInternal,
			Message:       "handler failed with non-retryable application error",
			Cause:         appErr,
			RetryBehavior: nexus.HandlerErrorRetryBehaviorNonRetryable,
		}
	}
	return convertServiceError(err)
}

// convertServiceError converts a serviceerror into a Nexus HandlerError if possible.
// If exposeDetails is true, the error message from the given error is exposed in the converted HandlerError, otherwise,
// a default message with minimal information is attached to the returned error.
// Roughly taken from https://github.com/googleapis/googleapis/blob/master/google/rpc/code.proto
// and
// https://github.com/grpc-ecosystem/grpc-gateway/blob/a7cf811e6ffabeaddcfb4ff65602c12671ff326e/runtime/errors.go#L56.
func convertServiceError(err error) error {
	var st *status.Status

	// Temporal serviceerrors have a Status() method.
	stGetter, ok := err.(interface{ Status() *status.Status })
	if !ok {
		// Not a serviceerror, passthrough.
		return err
	}

	st = stGetter.Status()

	switch st.Code() {
	case codes.InvalidArgument:
		return &nexus.HandlerError{Type: nexus.HandlerErrorTypeBadRequest, Cause: err}
	case codes.AlreadyExists, codes.FailedPrecondition, codes.OutOfRange:
		return &nexus.HandlerError{Type: nexus.HandlerErrorTypeInternal, Cause: err, RetryBehavior: nexus.HandlerErrorRetryBehaviorNonRetryable}
	case codes.Aborted, codes.Unavailable:
		return &nexus.HandlerError{Type: nexus.HandlerErrorTypeUnavailable, Cause: err}
	case codes.Canceled, codes.DataLoss, codes.Internal, codes.Unknown, codes.Unauthenticated, codes.PermissionDenied:
		// Note that codes.Unauthenticated, codes.PermissionDenied have Nexus error types but we convert to internal
		// because this is not a client auth error and happens when the handler fails to auth with Temporal and should
		// be considered retryable.
		return &nexus.HandlerError{Type: nexus.HandlerErrorTypeInternal, Cause: err}
	case codes.NotFound:
		return &nexus.HandlerError{Type: nexus.HandlerErrorTypeNotFound, Cause: err}
	case codes.ResourceExhausted:
		return &nexus.HandlerError{Type: nexus.HandlerErrorTypeResourceExhausted, Cause: err}
	case codes.Unimplemented:
		return &nexus.HandlerError{Type: nexus.HandlerErrorTypeNotImplemented, Cause: err}
	case codes.DeadlineExceeded:
		return &nexus.HandlerError{Type: nexus.HandlerErrorTypeUpstreamTimeout, Cause: err}
	}

	return err
}

package internal

import (
	"context"
	"errors"
	"time"

	"github.com/nexus-rpc/sdk-go/nexus"
	commonpb "go.temporal.io/api/common/v1"
	enumspb "go.temporal.io/api/enums/v1"
	taskqueuepb "go.temporal.io/api/taskqueue/v1"
	"go.temporal.io/api/workflowservice/v1"
	"go.temporal.io/sdk/internal/common/metrics"
	"go.temporal.io/sdk/log"
)

type nexusTaskPoller struct {
	basePoller
	namespace              string
	taskQueueName          string
	identity               string
	service                workflowservice.WorkflowServiceClient
	taskHandler            *nexusTaskHandler
	logger                 log.Logger
	numPollerMetric        *numPollerMetric
	inboundPayloadVisitor  PayloadVisitor
	outboundPayloadVisitor PayloadVisitor
	backgroundContext      context.Context
	pollerGroups           *pollerGroupManager
}

type nexusTask struct {
	task *workflowservice.PollNexusTaskQueueResponse
}

var _ taskPoller = &nexusTaskPoller{}

func newNexusTaskPoller(
	taskHandler *nexusTaskHandler,
	service workflowservice.WorkflowServiceClient,
	params workerExecutionParameters,
	pollerGroups *pollerGroupManager,
) *nexusTaskPoller {
	backgroundContext := params.BackgroundContext
	if backgroundContext == nil {
		backgroundContext = context.Background()
	}
	return &nexusTaskPoller{
		basePoller: basePoller{
			metricsHandler:               params.MetricsHandler,
			rpcTimeout:                   params.RPCTimeout,
			stopC:                        params.WorkerStopChannel,
			workerBuildID:                params.getBuildID(),
			useBuildIDVersioning:         params.UseBuildIDForVersioning,
			workerDeploymentVersion:      params.DeploymentOptions.Version,
			capabilities:                 params.capabilities,
			pollTimeTracker:              params.pollTimeTracker,
			workerInstanceKey:            params.workerInstanceKey,
			pollerGroupSnapshotStore:     params.pollerGroupSnapshotStore,
			workerPollCompleteOnShutdown: params.workerPollCompleteOnShutdown,
		},
		taskHandler:     taskHandler,
		service:         service,
		namespace:       params.Namespace,
		taskQueueName:   params.TaskQueue,
		identity:        params.Identity,
		logger:          params.Logger,
		numPollerMetric: newNumPollerMetric(params.MetricsHandler, metrics.PollerTypeNexusTask),

		inboundPayloadVisitor:  params.inboundPayloadVisitor,
		outboundPayloadVisitor: params.outboundPayloadVisitor,
		backgroundContext:      backgroundContext,
		pollerGroups:           pollerGroups,
	}
}

// Poll the nexus task queue and update the num_poller metric
func (ntp *nexusTaskPoller) pollNexusTaskQueue(ctx context.Context, request *workflowservice.PollNexusTaskQueueRequest) (*workflowservice.PollNexusTaskQueueResponse, error) {
	ntp.numPollerMetric.increment()
	defer ntp.numPollerMetric.decrement()

	return ntp.service.PollNexusTaskQueue(ctx, request)
}

func (ntp *nexusTaskPoller) poll(
	ctx context.Context,
	lease pollerGroupLease,
) (taskForWorker, error) {
	if lease.owner != nil && lease.owner != ntp.pollerGroups {
		return nil, errors.New("nexus poller-group lease belongs to a different manager")
	}

	traceLog(func() {
		ntp.logger.Debug("nexusTaskPoller::Poll")
	})
	request := &workflowservice.PollNexusTaskQueueRequest{
		Namespace: ntp.namespace,
		TaskQueue: &taskqueuepb.TaskQueue{Name: ntp.taskQueueName, Kind: enumspb.TASK_QUEUE_KIND_NORMAL},
		Identity:  ntp.identity,
		//lint:ignore SA1019 retain legacy Build ID versioning metadata for older servers
		WorkerVersionCapabilities: &commonpb.WorkerVersionCapabilities{
			BuildId:              ntp.workerBuildID,
			UseVersioning:        ntp.useBuildIDVersioning,
			DeploymentSeriesName: ntp.workerDeploymentVersion.DeploymentName,
		},
		DeploymentOptions: workerDeploymentOptionsToProto(
			ntp.useBuildIDVersioning,
			ntp.workerDeploymentVersion,
		),
		WorkerInstanceKey: ntp.workerInstanceKey,
		PollerPoolInfo:    ntp.getPollerPoolInfo(),
	}

	request.PollerGroupId = lease.groupIDOrEmpty()

	response, err := ntp.pollNexusTaskQueue(ctx, request)
	if err != nil {
		return nil, err
	}
	if response != nil && response.GetPollerGroupsInfo() != nil {
		ntp.updatePollerGroups(response.GetPollerGroupsInfo())
	}
	if response == nil || len(response.TaskToken) == 0 {
		// No operation info is available on empty poll. Emit using base scope.
		ntp.metricsHandler.Counter(metrics.NexusPollNoTaskCounter).Inc(1)
		return nil, nil
	}

	ntp.pollTimeTracker.recordPollSuccess(metrics.PollerTypeNexusTask)

	return &nexusTask{task: response}, nil
}

// PollTask polls a new task
func (ntp *nexusTaskPoller) PollTask(lease pollerGroupLease) (taskForWorker, error) {
	return ntp.doPoll(func(ctx context.Context) (taskForWorker, error) {
		return ntp.poll(ctx, lease)
	})
}

// ProcessTask processes a new task
func (ntp *nexusTaskPoller) ProcessTask(task any) error {
	if !ntp.shouldDrainOnShutdown() && ntp.stopping() {
		return errStop
	}

	response := task.(*nexusTask).task
	if response.GetRequest() == nil {
		// We didn't get a request, poll must have timed out.
		traceLog(func() {
			ntp.logger.Debug("Empty Nexus poll response")
		})
		return nil
	}

	executionStartTime := time.Now()

	// Schedule-to-start (from the time the request hit the frontend).
	// Note that this metric does not include the service and operation name as they are not relevant when polling from
	// the Nexus task queue.
	scheduleToStartLatency := executionStartTime.Sub(response.GetRequest().GetScheduledTime().AsTime())
	ntp.metricsHandler.WithTags(metrics.TaskQueueTags(ntp.taskQueueName)).Timer(metrics.NexusTaskScheduleToStartLatency).Record(scheduleToStartLatency)

	nctx, handlerErr := ntp.taskHandler.newNexusOperationContext(response)
	if handlerErr != nil {
		// context wasn't propagated to us, use a background context.
		failedRequest, err := ntp.taskHandler.fillInFailure(
			response.TaskToken,
			handlerErr,
			getEffectiveTemporalFailureResponses(response.GetRequest().GetCapabilities().GetTemporalFailureResponses()),
			ntp.taskHandler.failureConverter,
			response.GetPollerGroupId(),
		)
		if err != nil {
			return err
		}
		_, err = ntp.taskHandler.client.WorkflowService().RespondNexusTaskFailed(
			context.Background(), failedRequest)
		return err
	}

	// Retrieve any operation input payloads that were offloaded to external storage
	// before the handler consumes them. A Nexus task carries at most one input and
	// one result payload, so payload visits are unconcurrent (the configurable
	// visit concurrency is scoped to workflow tasks).
	if visitErr := visitProtoPayloads(ntp.backgroundContext, ntp.inboundPayloadVisitor, response, 0); visitErr != nil {
		return ntp.reportExternalStorageFailure(response, "retrieve Nexus operation input from external storage", visitErr)
	}

	// Process the nexus task.
	res, failure, err := ntp.taskHandler.ExecuteContext(nctx, response)

	// Execution latency (in-SDK processing time).
	nctx.metricsHandler.Timer(metrics.NexusTaskExecutionLatency).Record(time.Since(executionStartTime))

	// Increment failure in all forms of errors:
	// Internal error processing the task.
	// Failure from user handler.
	// Special case for the start response with operation error.
	if err != nil {
		var failureTag string
		if err == errNexusTaskTimeout {
			failureTag = "timeout"
		} else {
			failureTag = "internal_sdk_error"
		}
		nctx.log.Error("Error processing nexus task", "error", err)
		nctx.metricsHandler.
			WithTags(metrics.NexusTaskFailureTags(failureTag)).
			Counter(metrics.NexusTaskExecutionFailedCounter).
			Inc(1)
	} else if failure != nil {
		//lint:ignore SA1019 handle legacy operation error format for backward compatibility.
		taskErr := failure.GetError()
		if taskErr != nil {
			nctx.metricsHandler.
				WithTags(metrics.NexusTaskFailureTags("handler_error_" + taskErr.GetErrorType())).
				Counter(metrics.NexusTaskExecutionFailedCounter).
				Inc(1)
		} else if failure.GetFailure() != nil {
			// Failure must contain a NexusHandlerFailureInfo
			nctx.metricsHandler.
				WithTags(metrics.NexusTaskFailureTags("handler_error_" + failure.GetFailure().GetNexusHandlerFailureInfo().GetType())).
				Counter(metrics.NexusTaskExecutionFailedCounter).
				Inc(1)
		}
		//lint:ignore SA1019 handle legacy operation error format for backward compatibility.
	} else if e := res.Response.GetStartOperation().GetOperationError(); e != nil {
		nctx.metricsHandler.
			WithTags(metrics.NexusTaskFailureTags("operation_" + e.GetOperationState())).
			Counter(metrics.NexusTaskExecutionFailedCounter).
			Inc(1)
	} else if f := res.Response.GetStartOperation().GetFailure(); f != nil {
		if sf := f.GetApplicationFailureInfo(); sf != nil {
			nctx.metricsHandler.
				WithTags(metrics.NexusTaskFailureTags("operation_" + string(nexus.OperationStateFailed))).
				Counter(metrics.NexusTaskExecutionFailedCounter).
				Inc(1)
		} else if cf := f.GetCanceledFailureInfo(); cf != nil {
			nctx.metricsHandler.
				WithTags(metrics.NexusTaskFailureTags("operation_" + string(nexus.OperationStateCanceled))).
				Counter(metrics.NexusTaskExecutionFailedCounter).
				Inc(1)
		}
	}

	// Let the poller machinery drop the task, nothing to report back.
	// This is only expected due to context deadline errors.
	if err != nil {
		return err
	}

	// Offload any large result or failure payloads to external storage before reporting.
	if res != nil {
		if visitErr := visitProtoPayloads(ntp.backgroundContext, ntp.outboundPayloadVisitor, res, 0); visitErr != nil {
			return ntp.reportExternalStorageFailure(response, "store Nexus operation result in external storage", visitErr)
		}
	} else if failure != nil {
		if visitErr := visitProtoPayloads(ntp.backgroundContext, ntp.outboundPayloadVisitor, failure, 0); visitErr != nil {
			return ntp.reportExternalStorageFailure(response, "store Nexus operation failure in external storage", visitErr)
		}
	}

	if err := ntp.reportCompletion(res, failure); err != nil {
		traceLog(func() {
			ntp.logger.Debug("reportNexusTaskComplete failed", tagError, err)
		})
		return err
	}

	// E2E latency, from frontend until we finished reporting completion.
	nctx.metricsHandler.
		Timer(metrics.NexusTaskEndToEndLatency).
		Record(time.Since(response.GetRequest().GetScheduledTime().AsTime()))
	return nil
}

func (ntp *nexusTaskPoller) reportCompletion(
	completion *workflowservice.RespondNexusTaskCompletedRequest,
	failure *workflowservice.RespondNexusTaskFailedRequest,
) error {
	ctx := context.Background()
	// No workflow or activity tags to report.
	// Task queue expected to be empty for Respond*Task... requests.
	rpcMetricsHandler := ntp.metricsHandler.WithTags(metrics.RPCTags(metrics.NoneTagValue, metrics.NoneTagValue, metrics.NoneTagValue))
	ctx, cancel := newGRPCContext(ctx, ntp.rpcTimeout, grpcMetricsHandler(rpcMetricsHandler),
		defaultGrpcRetryParameters(ctx))
	defer cancel()

	if failure != nil {
		_, err := ntp.taskHandler.client.WorkflowService().RespondNexusTaskFailed(ctx, failure)
		return err
	}
	_, err := ntp.taskHandler.client.WorkflowService().RespondNexusTaskCompleted(ctx, completion)
	return err
}

// reportExternalStorageFailure fails the task with a retryable internal error when
// external storage retrieval or offload fails, so the server redelivers the task.
func (ntp *nexusTaskPoller) reportExternalStorageFailure(
	response *workflowservice.PollNexusTaskQueueResponse,
	action string,
	cause error,
) error {
	handlerErr := nexus.NewHandlerErrorf(nexus.HandlerErrorTypeInternal, "failed to %s: %v", action, cause)
	failedRequest, err := ntp.taskHandler.fillInFailure(
		response.TaskToken,
		handlerErr,
		getEffectiveTemporalFailureResponses(response.GetRequest().GetCapabilities().GetTemporalFailureResponses()),
		ntp.taskHandler.failureConverter,
		response.GetPollerGroupId(),
	)
	if err != nil {
		return err
	}
	return ntp.reportCompletion(nil, failedRequest)
}

package internal

import (
	"github.com/nexus-rpc/sdk-go/nexus"
	enumspb "go.temporal.io/api/enums/v1"
	"go.temporal.io/api/workflowservice/v1"
	"go.temporal.io/sdk/internal/common/metrics"
)

type nexusWorkerOptions struct {
	executionParameters workerExecutionParameters
	client              Client
	workflowService     workflowservice.WorkflowServiceClient
	handler             nexus.Handler
	registry            *registry
}

type nexusWorker struct {
	executionParameters workerExecutionParameters
	workflowService     workflowservice.WorkflowServiceClient
	worker              *baseWorker
	// stopC is created by newNexusWorker, exposed to the Nexus task poller through
	// WorkerStopChannel, and closed by nexusWorker.Stop() during shutdown.
	stopC chan struct{}
}

func newNexusWorker(opts nexusWorkerOptions) (*nexusWorker, error) {
	workerStopChannel := make(chan struct{})
	params := opts.executionParameters
	params.WorkerStopChannel = getReadOnlyChannel(workerStopChannel)
	ensureRequiredParams(&params)
	var pollerGroups *pollerGroupManager
	if _, ok := params.NexusTaskPollerBehavior.(*pollerBehaviorAutoscaling); ok {
		pollerGroups = newPollerGroupManager(params.pollerGroupSnapshotStore)
	}
	poller := newNexusTaskPoller(
		newNexusTaskHandler(
			opts.handler,
			opts.executionParameters.Identity,
			opts.executionParameters.Namespace,
			opts.executionParameters.TaskQueue,
			opts.client,
			opts.executionParameters.DataConverter,
			opts.executionParameters.FailureConverter,
			opts.executionParameters.Logger,
			opts.executionParameters.MetricsHandler,
			opts.registry,
		),
		opts.workflowService,
		params,
		pollerGroups,
	)

	bwo := baseWorkerOptions{
		pollerRate:       defaultPollerRate,
		slotSupplier:     params.Tuner.GetNexusSlotSupplier(),
		maxTaskPerSecond: defaultWorkerTaskExecutionRate,
		taskPollers: []scalableTaskPoller{
			newScalableTaskPoller(
				poller,
				opts.executionParameters.Logger,
				params.NexusTaskPollerBehavior,
				metrics.PollerTypeNexusTask,
				params.serverSupportsAutoscaling,
				pollerGroups,
			),
		},
		taskProcessor:                poller,
		workerType:                   "NexusWorker",
		identity:                     params.Identity,
		buildId:                      params.getBuildID(),
		logger:                       params.Logger,
		stopTimeout:                  params.WorkerStopTimeout,
		fatalErrCb:                   params.WorkerFatalErrorCallback,
		noRepoll:                     params.noRepoll,
		metricsHandler:               params.MetricsHandler,
		workerPollCompleteOnShutdown: params.workerPollCompleteOnShutdown,
		slotReservationData: slotReservationData{
			taskQueue:     params.TaskQueue,
			taskQueueKind: enumspb.TASK_QUEUE_KIND_NORMAL,
		},
		isInternalWorker: params.isInternalWorker(),
	}

	baseWorker := newBaseWorker(bwo)

	return &nexusWorker{
		executionParameters: opts.executionParameters,
		workflowService:     opts.workflowService,
		worker:              baseWorker,
		stopC:               workerStopChannel,
	}, nil
}

// Start the worker.
func (w *nexusWorker) Start() error {
	w.worker.Start()
	return nil
}

// Stop the worker.
func (w *nexusWorker) Stop() {
	close(w.stopC)
	w.worker.Stop()
}

package internal

import (
	"math/rand"
	"sync"

	enumspb "go.temporal.io/api/enums/v1"
	taskqueuepb "go.temporal.io/api/taskqueue/v1"
)

type (
	// pollerGroupSnapshotStore holds one task queue's membership, weights, and
	// version. Poller kinds share it but keep their in-flight state local.
	pollerGroupSnapshotStore struct {
		mu      sync.RWMutex
		current pollerGroupSnapshot
		// changedCh is closed and replaced whenever a newer group snapshot is
		// accepted. Runners use it to observe updates published through any
		// poller sharing this store.
		changedCh chan struct{}
	}

	// pollerGroupSnapshot is immutable after publication.
	pollerGroupSnapshot struct {
		groups     map[string]pollerGroupSnapshotEntry
		version    int64
		versionSet bool
	}

	// pollerGroupKey identifies one observed lifetime of a group. Incarnation is
	// the snapshot version where the ID first appeared after being absent.
	pollerGroupKey struct {
		id          string
		incarnation int64
	}

	// pollerGroupSnapshotEntry binds a group's identity to its current weight.
	pollerGroupSnapshotEntry struct {
		key    pollerGroupKey
		weight float32
	}

	// pollerGroupManager assigns groups for autoscaling Activity and Nexus polls
	// and worker-command polls. Workflow polls use workflowAutoscalingBalancer.
	pollerGroupManager struct {
		groupStore *pollerGroupSnapshotStore
		mu         sync.Mutex
		groups     map[string]*pollerGroupState
	}

	// pollerGroupLease tracks one poll attempt's group reservation until release.
	pollerGroupLease struct {
		owner pollerGroupLeaseOwner
		group pollerGroupKey
		kind  enumspb.TaskQueueKind
	}

	pollerGroupLeaseOwner interface {
		releaseReservation(pollerGroupLease)
	}

	pollerGroupState struct {
		key              pollerGroupKey
		pendingPollCount int
	}
)

func newPollerGroupSnapshotStore() *pollerGroupSnapshotStore {
	return &pollerGroupSnapshotStore{
		current: pollerGroupSnapshot{
			groups: make(map[string]pollerGroupSnapshotEntry),
		},
		changedCh: make(chan struct{}),
	}
}

func newPollerGroupManager(groupStore *pollerGroupSnapshotStore) *pollerGroupManager {
	return &pollerGroupManager{
		groupStore: groupStore,
		groups:     make(map[string]*pollerGroupState),
	}
}

func (m *pollerGroupManager) requiredMin() int {
	return m.groupStore.len()
}

func (m *pollerGroupManager) reserve() pollerGroupLease {
	group := m.reserveGroup()
	return m.lease(group)
}

// tryReserveRequired reserves an uncovered current group when existing polls
// consume the autoscaling target, ensuring every group has minimum coverage.
// The bool reports whether a group was reserved.
func (m *pollerGroupManager) tryReserveRequired() (pollerGroupLease, bool) {
	m.mu.Lock()
	defer m.mu.Unlock()
	snapshot := m.syncGroupsLocked()

	group := m.reserveCandidate(m.coverageCandidates(snapshot.groups))
	if group == nil {
		return pollerGroupLease{}, false
	}
	return m.lease(group), true
}

func (m *pollerGroupManager) updateGroups(info *taskqueuepb.PollerGroupsInfo) {
	m.groupStore.updateGroups(info)
}

func (l pollerGroupLease) groupIDOrEmpty() string {
	return l.group.id
}

func (l pollerGroupLease) release() {
	if l.owner != nil {
		l.owner.releaseReservation(l)
	}
}

func (m *pollerGroupManager) lease(group *pollerGroupState) pollerGroupLease {
	// Poll ungrouped until the server advertises at least one group.
	if group == nil {
		return pollerGroupLease{owner: m}
	}
	return pollerGroupLease{owner: m, group: group.key}
}

func (m *pollerGroupManager) reserveGroup() *pollerGroupState {
	m.mu.Lock()
	defer m.mu.Unlock()
	snapshot := m.syncGroupsLocked()

	candidates := m.coverageCandidates(snapshot.groups)
	if len(candidates) == 0 {
		candidates = snapshot.groups
	}
	return m.reserveCandidate(candidates)
}

// coverageCandidates returns groups without an in-flight poll from this manager.
func (m *pollerGroupManager) coverageCandidates(
	groups map[string]pollerGroupSnapshotEntry,
) map[string]pollerGroupSnapshotEntry {
	candidates := make(map[string]pollerGroupSnapshotEntry)
	for groupID, group := range m.groups {
		if group.pendingPollCount == 0 {
			candidates[groupID] = groups[groupID]
		}
	}
	return candidates
}

func (m *pollerGroupManager) reserveCandidate(
	candidates map[string]pollerGroupSnapshotEntry,
) *pollerGroupState {
	groupID := choosePollerGroup(candidates)
	if groupID == "" {
		return nil
	}
	group := m.groups[groupID]
	group.pendingPollCount++
	return group
}

func (m *pollerGroupManager) releaseReservation(lease pollerGroupLease) {
	if lease.group.id == "" {
		return
	}
	m.mu.Lock()
	group := m.groups[lease.group.id]
	if group != nil && group.key == lease.group && group.pendingPollCount > 0 {
		group.pendingPollCount--
	}
	m.mu.Unlock()
}

// syncGroupsLocked reconciles local groups with the current store snapshot.
// The caller must hold m.mu so snapshots cannot be applied out of order.
func (m *pollerGroupManager) syncGroupsLocked() pollerGroupSnapshot {
	snapshot := m.groupStore.snapshot()
	for groupID, entry := range snapshot.groups {
		group := m.groups[groupID]
		if group == nil || group.key != entry.key {
			m.groups[groupID] = &pollerGroupState{key: entry.key}
		}
	}
	for groupID := range m.groups {
		if _, ok := snapshot.groups[groupID]; !ok {
			delete(m.groups, groupID)
		}
	}

	return snapshot
}

// choosePollerGroup picks a random group using the configured weights.
// If all weights are zero or negative, it picks uniformly from all groups.
// If floating-point rounding prevents the weighted walk from selecting a group,
// it falls back to the last positive-weight candidate encountered.
func choosePollerGroup(groups map[string]pollerGroupSnapshotEntry) string {
	if len(groups) == 0 {
		return ""
	}

	totalWeight := float32(0)
	for _, group := range groups {
		if group.weight > 0 {
			totalWeight += group.weight
		}
	}

	// if all weights are 0, pick randomly
	if totalWeight <= 0 {
		selected := rand.Intn(len(groups))
		for groupID := range groups {
			if selected == 0 {
				return groupID
			}
			selected--
		}
		return ""
	}

	// Pick a random point in [0, totalWeight). Subtract each group's weight
	// until the point is less than the current group's weight.
	point := rand.Float32() * totalWeight
	var lastCandidate string
	for groupID, group := range groups {
		if group.weight <= 0 {
			continue
		}
		lastCandidate = groupID
		if point < group.weight {
			return groupID
		}
		point -= group.weight
	}

	// Floating-point rounding fallback.
	return lastCandidate
}

func (s *pollerGroupSnapshotStore) len() int {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return len(s.current.groups)
}

func (s *pollerGroupSnapshotStore) snapshot() pollerGroupSnapshot {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return s.current
}

// observe returns a snapshot and the notification for its replacement.
func (s *pollerGroupSnapshotStore) observe() (pollerGroupSnapshot, <-chan struct{}) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return s.current, s.changedCh
}

func (s *pollerGroupSnapshotStore) updateGroups(info *taskqueuepb.PollerGroupsInfo) {
	if info == nil {
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	if s.current.versionSet && info.GetVersion() <= s.current.version {
		return
	}

	groups := make(map[string]pollerGroupSnapshotEntry, len(info.GetPollerGroups()))
	for _, group := range info.GetPollerGroups() {
		if groupID := group.GetId(); groupID != "" {
			entry, ok := s.current.groups[groupID]
			if !ok {
				entry.key = pollerGroupKey{id: groupID, incarnation: info.GetVersion()}
			}
			entry.weight = group.GetWeight()
			groups[groupID] = entry
		}
	}

	s.current = pollerGroupSnapshot{
		groups:     groups,
		version:    info.GetVersion(),
		versionSet: true,
	}
	close(s.changedCh)
	s.changedCh = make(chan struct{})
}

