func getActivityResourceId(workflowId, activityId string) string {
	if workflowId != "" {
		return getWorkflowResourceId(workflowId)
	}
	if activityId != "" {
		return fmt.Sprintf("activity:%s", activityId)
	}
	return ""
}

func getWorkflowResourceId(workflowId string) string {
	if workflowId == "" {
		return ""
	}
	return fmt.Sprintf("workflow:%s", workflowId)
}

func convertActivityResultToRespondRequest(
	identity string,
	taskToken []byte,
	result *commonpb.Payloads,
	err error,
	dataConverter converter.DataConverter,
	failureConverter converter.FailureConverter,
	namespace string,
	cancelAllowed bool,
	versionStamp *commonpb.WorkerVersionStamp,
	deployment *deploymentpb.Deployment,
	workerDeploymentOptions *deploymentpb.WorkerDeploymentOptions,
	workflowId string,
	activityId string,
) any {
	if err == ErrActivityResultPending {
		// activity result is pending and will be completed asynchronously.
		// nothing to report at this point
		return ErrActivityResultPending
	}

	if err == nil {
		return &workflowservice.RespondActivityTaskCompletedRequest{
			TaskToken:  taskToken,
			Result:     result,
			Identity:   identity,
			Namespace:  namespace,
			ResourceId: getActivityResourceId(workflowId, activityId),
			//lint:ignore SA1019 retain legacy Build ID versioning metadata for older servers
			WorkerVersion: versionStamp,
			//lint:ignore SA1019 retain legacy deployment metadata for servers predating deployment options
			Deployment:        deployment,
			DeploymentOptions: workerDeploymentOptions,
		}
	}

	// Only respond with canceled if allowed
	if cancelAllowed {
		var canceledErr *CanceledError
		if errors.As(err, &canceledErr) {
			return &workflowservice.RespondActivityTaskCanceledRequest{
				TaskToken:  taskToken,
				Details:    convertErrDetailsToPayloads(canceledErr.details, dataConverter),
				Identity:   identity,
				Namespace:  namespace,
				ResourceId: getActivityResourceId(workflowId, activityId),
				//lint:ignore SA1019 retain legacy Build ID versioning metadata for older servers
				WorkerVersion: versionStamp,
				//lint:ignore SA1019 retain legacy deployment metadata for servers predating deployment options
				Deployment:        deployment,
				DeploymentOptions: workerDeploymentOptions,
			}
		}
		if errors.Is(err, context.Canceled) {
			return &workflowservice.RespondActivityTaskCanceledRequest{
				TaskToken:  taskToken,
				Identity:   identity,
				Namespace:  namespace,
				ResourceId: getActivityResourceId(workflowId, activityId),
				//lint:ignore SA1019 retain legacy Build ID versioning metadata for older servers
				WorkerVersion: versionStamp,
				//lint:ignore SA1019 retain legacy deployment metadata for servers predating deployment options
				Deployment:        deployment,
				DeploymentOptions: workerDeploymentOptions,
			}
		}
	}

	// If a canceled error is returned but it wasn't allowed, we have to wrap in
	// an unexpected-cancel application error
	if _, isCanceledErr := err.(*CanceledError); isCanceledErr {
		err = fmt.Errorf("unexpected activity cancel error: %w", err)
	}

	return &workflowservice.RespondActivityTaskFailedRequest{
		TaskToken:  taskToken,
		Failure:    failureConverter.ErrorToFailure(err),
		Identity:   identity,
		Namespace:  namespace,
		ResourceId: getActivityResourceId(workflowId, activityId),
		//lint:ignore SA1019 retain legacy Build ID versioning metadata for older servers
		WorkerVersion: versionStamp,
		//lint:ignore SA1019 retain legacy deployment metadata for servers predating deployment options
		Deployment:        deployment,
		DeploymentOptions: workerDeploymentOptions,
	}
}

