func getCpuUsage(supplier SysInfoProvider, logger log.Logger) float32 {
	if supplier == nil {
		return 0
	}
	cpu, err := supplier.CpuUsage(&SysInfoContext{Logger: logger})
	if err != nil {
		logger.Warn("Failed to get CPU usage for heartbeat", "error", err)
		return 0
	}
	return float32(cpu)
}

