// heartbeatManager manages heartbeat workers across namespaces for a client.
type heartbeatManager struct {
	client   *WorkflowClient
	interval time.Duration
	logger   log.Logger
	// environmentInfo is reported once per worker, or nil when reporting is disabled.
	environmentInfo *workerpb.EnvironmentInfo

	workersMutex sync.Mutex
	workers      map[string]*sharedNamespaceWorker // namespace -> worker
}

// newHeartbeatManager creates a new heartbeatManager.
func newHeartbeatManager(client *WorkflowClient, interval time.Duration, logger log.Logger, disableEnvironmentInfo bool) *heartbeatManager {
	if logger == nil {
		logger = ilog.NewDefaultLogger()
	}
	var environmentInfo *workerpb.EnvironmentInfo
	if !disableEnvironmentInfo {
		environmentInfo = detectEnvironmentInfo()
	}
	return &heartbeatManager{
		client:          client,
		interval:        interval,
		logger:          logger,
		environmentInfo: environmentInfo,
		workers:         make(map[string]*sharedNamespaceWorker),
	}
}

func (m *heartbeatManager) sharedNamespaceWorkerFor(namespace string) *sharedNamespaceWorker {
	m.workersMutex.Lock()
	defer m.workersMutex.Unlock()
	return m.sharedNamespaceWorkerForLocked(namespace)
}

func (m *heartbeatManager) sharedNamespaceWorkerForLocked(namespace string) *sharedNamespaceWorker {
	hw := m.workers[namespace]
	if hw != nil {
		return hw
	}
	// If this is the first worker on the namespace, start a new shared namespace worker.
	heartbeatCtx, heartbeatCancel := context.WithCancel(context.Background())
	controlTaskQueue := workerControlTaskQueue(namespace, m.client.workerGroupingKey)
	metricsHandler := m.client.metricsHandler
	if metricsHandler == nil {
		metricsHandler = metrics.NopHandler
	}
	hw = &sharedNamespaceWorker{
		client:                        m.client,
		namespace:                     namespace,
		interval:                      m.interval,
		workerCtx:                     heartbeatCtx,
		heartbeatCancel:               heartbeatCancel,
		callbacks:                     make(map[string]func() *workerpb.WorkerHeartbeat),
		heartbeatSuccessCallbacks:     make(map[string]func()),
		activityCancellationCallbacks: newActivityCancellationCallbacks(),
		workerControlTaskQueue:        controlTaskQueue,
		workerInstanceKey:             uuid.NewString(),
		metricsHandler:                metricsHandler,
		stopC:                         make(chan struct{}),
		stoppedC:                      make(chan struct{}),
		logger:                        m.logger,
		pollerGroups:                  newPollerGroupManager(newPollerGroupSnapshotStore()),
	}
	m.workers[namespace] = hw
	return hw
}

// registerWorker registers a worker's heartbeat callback with the shared heartbeat worker for the namespace.
func (m *heartbeatManager) registerWorker(
	worker *AggregatedWorker,
) error {
	nsData, err := m.client.loadNamespaceData(worker.heartbeatMetrics)
	if err != nil {
		return fmt.Errorf("failed to get namespace capabilities: %w", err)
	}
	if !nsData.capabilities.GetWorkerHeartbeats() {
		if m.logger != nil {
			m.logger.Debug("Worker heartbeating configured, but server version does not support it.")
		}
		return nil
	}

	namespace := worker.executionParams.Namespace
	m.workersMutex.Lock()
	defer m.workersMutex.Unlock()

	hw := m.sharedNamespaceWorkerForLocked(namespace)
	hw.pollerGroups.updateGroups(nsData.pollerGroupsInfo)

	hw.callbacksMutex.Lock()
	hw.callbacks[worker.workerInstanceKey] = worker.heartbeatCallback
	hw.heartbeatSuccessCallbacks[worker.workerInstanceKey] = worker.heartbeatSuccess
	hw.callbacksMutex.Unlock()

	if hw.started.CompareAndSwap(false, true) {
		hw.workerCommandsSupported = nsData.capabilities.GetWorkerCommands()
		go hw.run()
	}

	return nil
}

// unregisterWorker removes a worker's heartbeat callback. If no callbacks remain for the namespace,
// the shared heartbeat worker is stopped.
func (m *heartbeatManager) unregisterWorker(worker *AggregatedWorker) {
	m.workersMutex.Lock()
	defer m.workersMutex.Unlock()

	namespace := worker.executionParams.Namespace
	hw, ok := m.workers[namespace]
	if !ok {
		return
	}

	hw.callbacksMutex.Lock()
	delete(hw.callbacks, worker.workerInstanceKey)
	delete(hw.heartbeatSuccessCallbacks, worker.workerInstanceKey)
	remaining := len(hw.callbacks)
	hw.callbacksMutex.Unlock()

	if remaining == 0 {
		hw.stop()
		delete(m.workers, namespace)
	}
}

// sharedNamespaceWorker handles heartbeating for all workers in a specific namespace for a specific client.
type sharedNamespaceWorker struct {
	client    *WorkflowClient
	namespace string
	interval  time.Duration
	logger    log.Logger

	workerCtx       context.Context
	heartbeatCancel context.CancelFunc

	// callbacksMutex should only be unlocked under
	callbacksMutex sync.RWMutex
	callbacks      map[string]func() *workerpb.WorkerHeartbeat // workerInstanceKey -> callback
	// heartbeatSuccessCallbacks are invoked after the server accepts a heartbeat batch that
	// included the corresponding worker. Guarded by callbacksMutex.
	heartbeatSuccessCallbacks map[string]func() // workerInstanceKey -> callback

	activityCancellationCallbacks *activityCancellationCallbacks
	workerCommandsSupported       bool
	workerCommandsRunning         atomic.Bool
	workerControlTaskQueue        string
	workerInstanceKey             string
	metricsHandler                metrics.Handler
	pollerGroups                  *pollerGroupManager

	// stopC is created when the namespace heartbeat worker starts and closed by
	// sharedNamespaceWorker.stop() to tell run() to exit.
	stopC chan struct{}
	// stoppedC is created with stopC and closed by sharedNamespaceWorker.run()
	// after the heartbeat loop exits. stop() waits on it before returning.
	stoppedC chan struct{}
	started  atomic.Bool
}

// Only advertise the queue while its command poller is running.
func (hw *sharedNamespaceWorker) controlTaskQueue() string {
	if hw == nil || !hw.workerCommandsRunning.Load() {
		return ""
	}
	return hw.workerControlTaskQueue
}

func (hw *sharedNamespaceWorker) run() {
	defer close(hw.stoppedC)

	if hw.workerCommandsSupported {
		workerCommandsDone := make(chan struct{})
		go func() {
			defer close(workerCommandsDone)
			hw.runWorkerCommands()
		}()
		defer func() {
			hw.heartbeatCancel()
			<-workerCommandsDone
		}()
	}

	ticker := time.NewTicker(hw.interval)
	defer ticker.Stop()

	if err := hw.sendHeartbeats(); err != nil {
		hw.logger.Warn("Stopping heartbeat worker", "error", err)
		return
	}

	for {
		select {
		case <-ticker.C:
			if err := hw.sendHeartbeats(); err != nil {
				hw.logger.Warn("Stopping heartbeat worker", "error", err)
				return
			}
		case <-hw.stopC:
			return
		}
	}
}

func (hw *sharedNamespaceWorker) sendHeartbeats() error {
	hw.callbacksMutex.RLock()
	callbacks := make([]func() *workerpb.WorkerHeartbeat, 0, len(hw.callbacks))
	successCallbacks := make([]func(), 0, len(hw.callbacks))
	for key, cb := range hw.callbacks {
		if cb != nil {
			callbacks = append(callbacks, cb)
			if onSuccess := hw.heartbeatSuccessCallbacks[key]; onSuccess != nil {
				successCallbacks = append(successCallbacks, onSuccess)
			}
		}
	}
	hw.callbacksMutex.RUnlock()

	if len(callbacks) == 0 {
		return nil
	}

	heartbeats := make([]*workerpb.WorkerHeartbeat, 0, len(callbacks))
	for _, cb := range callbacks {
		heartbeats = append(heartbeats, cb())
	}

	_, err := hw.client.recordWorkerHeartbeat(hw.workerCtx, &workflowservice.RecordWorkerHeartbeatRequest{
		Namespace:       hw.namespace,
		Identity:        hw.client.identity,
		WorkerHeartbeat: heartbeats,
		ResourceId:      fmt.Sprintf("worker:%s", hw.client.workerGroupingKey),
	})
	if err != nil {
		if status.Code(err) == codes.Unimplemented {
			// Server doesn't support heartbeats; return error to stop the worker.
			return fmt.Errorf("server does not support worker heartbeats: %w", err)
		}
		// For other errors, log and continue heartbeating
		hw.logger.Warn("Failed to send heartbeat", "Error", err)
		return nil
	}

	for _, onSuccess := range successCallbacks {
		onSuccess()
	}
	return nil
}

func (hw *sharedNamespaceWorker) runWorkerCommands() {
	pollerRunner := newAutoscalingTaskPollerRunner(
		newPollerAutoscaler(pollerAutoscalerOptions{
			initialPollerCount: 1,
			maxPollerCount:     1,
			minPollerCount:     1,
		}),
		hw.pollerGroups,
	)
	var pollWG sync.WaitGroup
	defer pollWG.Wait()
	hw.workerCommandsRunning.Store(true)
	defer hw.workerCommandsRunning.Store(false)

	for {
		if hw.workerCtx.Err() != nil {
			return
		}

		admission, err := pollerRunner.acquire(hw.workerCtx)
		if err != nil {
			return
		}

		pollWG.Go(func() {
			defer admission.release()

			task, err := hw.pollWorkerCommand(admission.groupLease)
			if err != nil {
				if hw.workerCtx.Err() == nil {
					hw.logger.Warn("Failed polling worker command task", "Error", err)
				}
				timer := time.NewTimer(time.Second)
				defer timer.Stop()
				select {
				case <-timer.C:
				case <-hw.workerCtx.Done():
				}
				return
			}

			if task == nil {
				return
			}

			if err := hw.handleWorkerCommandTask(task); err != nil {
				hw.logger.Warn("Failed handling worker command task", "Error", err)
			}
		})
	}
}

func (hw *sharedNamespaceWorker) pollWorkerCommand(
	lease pollerGroupLease,
) (
	*workflowservice.PollNexusTaskQueueResponse,
	error,
) {
	task, err := hw.pollWorkerCommandTask(lease.groupIDOrEmpty())
	if err != nil {
		return nil, err
	}
	if task != nil {
		hw.pollerGroups.updateGroups(task.GetPollerGroupsInfo())
	}
	if task == nil || len(task.TaskToken) == 0 {
		return nil, nil
	}
	if task.GetRequest() == nil {
		hw.logger.Warn("Received worker command task with nil request")
		return nil, nil
	}
	return task, nil
}

func (hw *sharedNamespaceWorker) pollWorkerCommandTask(
	pollerGroupID string,
) (*workflowservice.PollNexusTaskQueueResponse, error) {
	rpcMetricsHandler := hw.metricsHandler.WithTags(metrics.TaskQueueTags(hw.workerControlTaskQueue))
	grpcCtx, cancel := newGRPCContext(
		hw.workerCtx,
		hw.client.rpcTimeout,
		grpcMetricsHandler(rpcMetricsHandler),
		grpcLongPoll(true),
		grpcTimeout(pollTaskServiceTimeOut),
		defaultGrpcRetryParameters(hw.workerCtx),
	)
	defer cancel()

	return hw.client.workflowService.PollNexusTaskQueue(grpcCtx, &workflowservice.PollNexusTaskQueueRequest{
		Namespace: hw.namespace,
		TaskQueue: &taskqueuepb.TaskQueue{
			Name: hw.workerControlTaskQueue,
			Kind: enumspb.TASK_QUEUE_KIND_WORKER_COMMANDS,
		},
		Identity:          hw.client.identity,
		WorkerInstanceKey: hw.workerInstanceKey,
		DeploymentOptions: &deploymentpb.WorkerDeploymentOptions{
			BuildId:              "1.0",
			WorkerVersioningMode: enumspb.WORKER_VERSIONING_MODE_UNVERSIONED,
		},
		PollerGroupId: pollerGroupID,
	})
}

func (hw *sharedNamespaceWorker) handleWorkerCommandTask(task *workflowservice.PollNexusTaskQueueResponse) error {
	req := task.GetRequest()
	startOp := req.GetStartOperation()
	if startOp == nil {
		return fmt.Errorf("worker command nexus task has unexpected request variant")
	}

	var execReq workerservicepb.ExecuteCommandsRequest
	if err := proto.Unmarshal(startOp.GetPayload().GetData(), &execReq); err != nil {
		return fmt.Errorf("decoding ExecuteCommandsRequest: %w", err)
	}

	results := make([]*workerpb.WorkerCommandResult, 0, len(execReq.GetCommands()))
	for _, command := range execReq.GetCommands() {
		switch cmd := command.GetType().(type) {
		case *workerpb.WorkerCommand_CancelActivity:
			if cmd.CancelActivity != nil && hw.activityCancellationCallbacks != nil {
				hw.activityCancellationCallbacks.cancel(cmd.CancelActivity.GetTaskToken())
			}
			results = append(results, &workerpb.WorkerCommandResult{
				Type: &workerpb.WorkerCommandResult_CancelActivity{
					CancelActivity: &workerpb.CancelActivityResult{},
				},
			})
		default:
			hw.logger.Warn("Worker command has unsupported command type")
			results = append(results, &workerpb.WorkerCommandResult{})
		}
	}

	responsePayload, err := proto.Marshal(&workerservicepb.ExecuteCommandsResponse{Results: results})
	if err != nil {
		return fmt.Errorf("encode ExecuteCommandsResponse: %w", err)
	}

	grpcCtx, cancel := newGRPCContext(
		context.Background(),
		hw.client.rpcTimeout,
		grpcMetricsHandler(hw.metricsHandler),
		defaultGrpcRetryParameters(context.Background()),
	)
	defer cancel()
	_, err = hw.client.workflowService.RespondNexusTaskCompleted(grpcCtx, &workflowservice.RespondNexusTaskCompletedRequest{
		Namespace:     hw.namespace,
		Identity:      hw.client.identity,
		TaskToken:     task.TaskToken,
		PollerGroupId: task.PollerGroupId,
		Response: &nexuspb.Response{
			Variant: &nexuspb.Response_StartOperation{
				StartOperation: &nexuspb.StartOperationResponse{
					Variant: &nexuspb.StartOperationResponse_SyncSuccess{
						SyncSuccess: &nexuspb.StartOperationResponse_Sync{
							Payload: &commonpb.Payload{Data: responsePayload},
						},
					},
				},
			},
		},
	})
	if err != nil {
		return fmt.Errorf("complete worker command nexus task: %w", err)
	}
	return nil
}

func (hw *sharedNamespaceWorker) stop() {
	if !hw.started.CompareAndSwap(true, false) {
		return
	}
	if hw.heartbeatCancel != nil {
		hw.heartbeatCancel()
	}

	close(hw.stopC)
	<-hw.stoppedC
}

// pollerTargetTracker holds each poller type's target supplier, read live by the heartbeat.
// A type that never registers is reported as 0, which the proto defines as unknown.
type pollerTargetTracker struct {
	targets sync.Map // pollerType (string) -> func() int32
}

func (p *pollerTargetTracker) record(pollerType string, target func() int32) {
	if p == nil || pollerType == "" || target == nil {
		return
	}
	p.targets.Store(pollerType, target)
}

// pollTimeTracker tracks the last successful poll time for each poller type.
type pollTimeTracker struct {
	times sync.Map // pollerType (string) -> time.Time (stored as int64 nanos)
}

func (p *pollTimeTracker) recordPollSuccess(pollerType string) {
	p.times.Store(pollerType, time.Now().UnixNano())
}

func (p *pollTimeTracker) getLastPollTime(pollerType string) time.Time {
	if v, ok := p.times.Load(pollerType); ok {
		return time.Unix(0, v.(int64))
	}
	return time.Time{}
}

package internal

import (
	"sync"
	"sync/atomic"
	"time"

	workerpb "go.temporal.io/api/worker/v1"
	"google.golang.org/protobuf/types/known/timestamppb"

	"go.temporal.io/sdk/internal/common/metrics"
)

// Metrics we capture for heartbeat reporting.
var (
	capturedCounters = map[string]struct{}{
		metrics.StickyCacheHit:                      {},
		metrics.StickyCacheMiss:                     {},
		metrics.WorkflowTaskExecutionFailureCounter: {},
		metrics.ActivityExecutionFailedCounter:      {},
		metrics.LocalActivityExecutionFailedCounter: {},
		metrics.NexusTaskExecutionFailedCounter:     {},
	}

	// Timer recordings are counted (not their latencies) to track tasks processed.
	capturedTimers = map[string]struct{}{
		metrics.WorkflowTaskExecutionLatency:  {},
		metrics.ActivityExecutionLatency:      {},
		metrics.LocalActivityExecutionLatency: {},
		metrics.NexusTaskExecutionLatency:     {},
	}
)

// heartbeatMetricsHandler wraps a metrics handler and captures specific metrics
// in memory for worker heartbeats.
type heartbeatMetricsHandler struct {
	underlying metrics.Handler
	workerType string
	pollerType string

	// Keys are metric names, or "metricName:workerType" / "metricName:pollerType" for typed metrics.
	metrics *sync.Map
}

// newHeartbeatMetricsHandler creates a new handler that captures specific metrics
// for worker heartbeats while passing all metrics to the underlying handler.
func newHeartbeatMetricsHandler(underlying metrics.Handler) *heartbeatMetricsHandler {
	return &heartbeatMetricsHandler{
		underlying: underlying,
		metrics:    &sync.Map{},
	}
}

// forWorker creates a new handler that captures metrics specific to a worker type, for worker heartbeating.
// This should be called explicitly before calling WithTags on the returned handler.
func (h *heartbeatMetricsHandler) forWorker(workerType string) metrics.Handler {
	cpy := *h
	cpy.workerType = workerType
	return &cpy
}

// forPoller creates a new handler that captures metrics specific to a poller type, for worker heartbeating.
// This should be called explicitly before calling WithTags on the returned handler.
func (h *heartbeatMetricsHandler) forPoller(pollerType string) metrics.Handler {
	cpy := *h
	cpy.pollerType = pollerType
	return &cpy
}

func (h *heartbeatMetricsHandler) WithTags(tags map[string]string) metrics.Handler {
	cpy := *h
	cpy.underlying = h.underlying.WithTags(tags)
	return &cpy
}

func (h *heartbeatMetricsHandler) Counter(name string) metrics.Counter {
	underlying := h.underlying.Counter(name)
	if _, ok := capturedCounters[name]; ok {
		return &capturingCounter{
			underlying: underlying,
			value:      h.getOrCreate(name),
		}
	}
	return underlying
}

func (h *heartbeatMetricsHandler) Gauge(name string) metrics.Gauge {
	underlying := h.underlying.Gauge(name)

	switch name {
	case metrics.StickyCacheSize:
		return &capturingGauge{
			underlying: underlying,
			value:      h.getOrCreate(name),
		}
	case metrics.WorkerTaskSlotsAvailable, metrics.WorkerTaskSlotsUsed:
		if h.workerType != "" {
			return &capturingGauge{
				underlying: underlying,
				value:      h.getOrCreate(name + ":" + h.workerType),
			}
		}
	case metrics.NumPoller:
		if h.pollerType != "" {
			return &capturingGauge{
				underlying: underlying,
				value:      h.getOrCreate(name + ":" + h.pollerType),
			}
		}
	}

	return underlying
}

func (h *heartbeatMetricsHandler) Timer(name string) metrics.Timer {
	underlying := h.underlying.Timer(name)
	if _, ok := capturedTimers[name]; ok {
		return &capturingTimer{
			underlying: underlying,
			counter:    h.getOrCreate(name),
		}
	}
	return underlying
}

func (h *heartbeatMetricsHandler) getOrCreate(key string) *atomic.Int64 {
	if v, ok := h.metrics.Load(key); ok {
		return v.(*atomic.Int64)
	}
	v := new(atomic.Int64)
	actual, _ := h.metrics.LoadOrStore(key, v)
	return actual.(*atomic.Int64)
}

func (h *heartbeatMetricsHandler) get(key string) int64 {
	if v, ok := h.metrics.Load(key); ok {
		return v.(*atomic.Int64).Load()
	}
	return 0
}

// populateHeartbeatOptions contains extra information needed to populate heartbeats.
type populateHeartbeatOptions struct {
	workflowSlotSupplierKind      string
	activitySlotSupplierKind      string
	localActivitySlotSupplierKind string
	nexusSlotSupplierKind         string

	workflowPollerBehavior PollerBehavior
	activityPollerBehavior PollerBehavior
	nexusPollerBehavior    PollerBehavior

	// For delta calculations between heartbeats (mutated by PopulateHeartbeat).
	prevWorkflowProcessed      *int64
	prevWorkflowFailed         *int64
	prevActivityProcessed      *int64
	prevActivityFailed         *int64
	prevLocalActivityProcessed *int64
	prevLocalActivityFailed    *int64
	prevNexusProcessed         *int64
	prevNexusFailed            *int64

	pollTimeTracker *pollTimeTracker

	// pollerTargets holds each pool's target by poller type. Types this worker does not
	// run are absent and report 0, which the proto defines as unknown.
	pollerTargets map[string]int32
}

// PopulateHeartbeat fills in the metrics-related fields of the WorkerHeartbeat proto.
func (h *heartbeatMetricsHandler) PopulateHeartbeat(hb *workerpb.WorkerHeartbeat, opts *populateHeartbeatOptions) {
	hb.TotalStickyCacheHit = int32(h.get(metrics.StickyCacheHit))
	hb.TotalStickyCacheMiss = int32(h.get(metrics.StickyCacheMiss))
	hb.CurrentStickyCacheSize = int32(h.get(metrics.StickyCacheSize))

	if opts.workflowSlotSupplierKind != "" {
		hb.WorkflowTaskSlotsInfo = buildSlotsInfo(
			opts.workflowSlotSupplierKind,
			int32(h.get(metrics.WorkerTaskSlotsAvailable+":"+"WorkflowWorker")),
			int32(h.get(metrics.WorkerTaskSlotsUsed+":"+"WorkflowWorker")),
			h.get(metrics.WorkflowTaskExecutionLatency),
			h.get(metrics.WorkflowTaskExecutionFailureCounter),
			opts.prevWorkflowProcessed,
			opts.prevWorkflowFailed,
		)
	}

	if opts.activitySlotSupplierKind != "" {
		hb.ActivityTaskSlotsInfo = buildSlotsInfo(
			opts.activitySlotSupplierKind,
			int32(h.get(metrics.WorkerTaskSlotsAvailable+":"+"ActivityWorker")),
			int32(h.get(metrics.WorkerTaskSlotsUsed+":"+"ActivityWorker")),
			h.get(metrics.ActivityExecutionLatency),
			h.get(metrics.ActivityExecutionFailedCounter),
			opts.prevActivityProcessed,
			opts.prevActivityFailed,
		)
	}

	if opts.localActivitySlotSupplierKind != "" {
		hb.LocalActivitySlotsInfo = buildSlotsInfo(
			opts.localActivitySlotSupplierKind,
			int32(h.get(metrics.WorkerTaskSlotsAvailable+":"+"LocalActivityWorker")),
			int32(h.get(metrics.WorkerTaskSlotsUsed+":"+"LocalActivityWorker")),
			h.get(metrics.LocalActivityExecutionLatency),
			h.get(metrics.LocalActivityExecutionFailedCounter),
			opts.prevLocalActivityProcessed,
			opts.prevLocalActivityFailed,
		)
	}

	if opts.nexusSlotSupplierKind != "" {
		hb.NexusTaskSlotsInfo = buildSlotsInfo(
			opts.nexusSlotSupplierKind,
			int32(h.get(metrics.WorkerTaskSlotsAvailable+":"+"NexusWorker")),
			int32(h.get(metrics.WorkerTaskSlotsUsed+":"+"NexusWorker")),
			h.get(metrics.NexusTaskExecutionLatency),
			h.get(metrics.NexusTaskExecutionFailedCounter),
			opts.prevNexusProcessed,
			opts.prevNexusFailed,
		)
	}

	hb.WorkflowPollerInfo = buildPollerInfo(
		int32(h.get(metrics.NumPoller+":"+metrics.PollerTypeWorkflowTask)),
		opts.pollerTargets[metrics.PollerTypeWorkflowTask],
		opts.pollTimeTracker.getLastPollTime(metrics.PollerTypeWorkflowTask),
		opts.workflowPollerBehavior,
	)
	hb.WorkflowStickyPollerInfo = buildPollerInfo(
		int32(h.get(metrics.NumPoller+":"+metrics.PollerTypeWorkflowStickyTask)),
		opts.pollerTargets[metrics.PollerTypeWorkflowStickyTask],
		opts.pollTimeTracker.getLastPollTime(metrics.PollerTypeWorkflowStickyTask),
		opts.workflowPollerBehavior,
	)
	hb.ActivityPollerInfo = buildPollerInfo(
		int32(h.get(metrics.NumPoller+":"+metrics.PollerTypeActivityTask)),
		opts.pollerTargets[metrics.PollerTypeActivityTask],
		opts.pollTimeTracker.getLastPollTime(metrics.PollerTypeActivityTask),
		opts.activityPollerBehavior,
	)
	hb.NexusPollerInfo = buildPollerInfo(
		int32(h.get(metrics.NumPoller+":"+metrics.PollerTypeNexusTask)),
		opts.pollerTargets[metrics.PollerTypeNexusTask],
		opts.pollTimeTracker.getLastPollTime(metrics.PollerTypeNexusTask),
		opts.nexusPollerBehavior,
	)
}

func (h *heartbeatMetricsHandler) Unwrap() metrics.Handler {
	return h.underlying
}

func buildSlotsInfo(
	supplierKind string,
	slotsAvailable int32,
	slotsUsed int32,
	totalProcessed int64,
	totalFailed int64,
	prevProcessed *int64,
	prevFailed *int64,
) *workerpb.WorkerSlotsInfo {
	intervalProcessed := totalProcessed - *prevProcessed
	intervalFailed := totalFailed - *prevFailed

	*prevProcessed = totalProcessed
	*prevFailed = totalFailed

	return &workerpb.WorkerSlotsInfo{
		CurrentAvailableSlots:      slotsAvailable,
		CurrentUsedSlots:           slotsUsed,
		SlotSupplierKind:           supplierKind,
		TotalProcessedTasks:        int32(totalProcessed),
		TotalFailedTasks:           int32(totalFailed),
		LastIntervalProcessedTasks: int32(intervalProcessed),
		LastIntervalFailureTasks:   int32(intervalFailed),
	}
}

func buildPollerInfo(
	currentPollers int32,
	pollerTarget int32,
	lastSuccessfulPollTime time.Time,
	pollerBehavior PollerBehavior,
) *workerpb.WorkerPollerInfo {
	var isAutoscaling bool
	switch pollerBehavior.(type) {
	case *pollerBehaviorAutoscaling:
		isAutoscaling = true
	}
	var pollTime *timestamppb.Timestamp
	if !lastSuccessfulPollTime.IsZero() {
		pollTime = timestamppb.New(lastSuccessfulPollTime)
	}

	return &workerpb.WorkerPollerInfo{
		CurrentPollers:         currentPollers,
		TargetPollers:          pollerTarget,
		LastSuccessfulPollTime: pollTime,
		IsAutoscaling:          isAutoscaling,
	}
}

// capturingCounter wraps a counter and captures its value in memory.
type capturingCounter struct {
	underlying metrics.Counter
	value      *atomic.Int64
}

func (c *capturingCounter) Inc(delta int64) {
	c.underlying.Inc(delta)
	if delta > 0 {
		c.value.Add(delta)
	}
}

// capturingGauge wraps a gauge and captures its value in memory.
type capturingGauge struct {
	underlying metrics.Gauge
	value      *atomic.Int64
}

func (g *capturingGauge) Update(f float64) {
	g.underlying.Update(f)
	g.value.Store(int64(f))
}

// capturingTimer wraps a timer and increments a counter each time Record is called.
type capturingTimer struct {
	underlying metrics.Timer
	counter    *atomic.Int64
}

func (t *capturingTimer) Record(d time.Duration) {
	t.underlying.Record(d)
	t.counter.Add(1)
}

package internal

// All code in this file is private to the package.

import (
	"bytes"
	"errors"
	"fmt"
	"reflect"
	"runtime"
	"slices"
	"sort"
	"strings"
	"sync"
	"sync/atomic"
	"time"
	"unicode"

	commonpb "go.temporal.io/api/common/v1"
	enumspb "go.temporal.io/api/enums/v1"
	sdk "go.temporal.io/api/sdk/v1"

	"go.temporal.io/sdk/converter"
	"go.temporal.io/sdk/internal/common/metrics"
	"go.temporal.io/sdk/log"
)

const (
	defaultSignalChannelSize    = 100000 // really large buffering size(100K)
	defaultCoroutineExitTimeout = 100 * time.Millisecond

	panicIllegalAccessCoroutineState = "getState: illegal access from outside of workflow context"
	unhandledUpdateWarningMessage    = "[TMPRL1102] Workflow finished while update handlers are still running. This may have interrupted work that the" +
		" update handler was doing, and the client that sent the update will receive a 'workflow execution" +
		" already completed' RPCError instead of the update result. You can wait for all update" +
		" handlers to complete by using `workflow.Await(ctx, func() bool { return workflow.AllHandlersFinished(ctx) })`. Alternatively, if both you and the clients sending the update" +
		" are okay with interrupting running handlers when the workflow finishes, and causing clients to" +
		" receive errors, then you can disable this warning via UnfinishedPolicy in UpdateHandlerOptions."
)

type (
	syncWorkflowDefinition struct {
		workflow   workflow
		dispatcher dispatcher
		cancel     CancelFunc
		rootCtx    Context
	}

	workflowResult struct {
		workflowResult *commonpb.Payloads
		error          error
	}

	futureImpl struct {
		value   any
		err     error
		ready   bool
		channel *channelImpl
		chained []asyncFuture // Futures that are chained to this one
	}

	// Implements WaitGroup interface
	waitGroupImpl struct {
		n        int      // the number of coroutines to wait on
		waiting  bool     // indicates whether WaitGroup.Wait() has been called yet for the WaitGroup
		future   Future   // future to signal that all awaited members of the WaitGroup have completed
		settable Settable // used to unblock the future when all coroutines have completed
	}

	// Implements Mutex interface
	mutexImpl struct {
		locked bool
	}

	// Implements Semaphore interface
	semaphoreImpl struct {
		size int64
		cur  int64
	}

	// Dispatcher is a container of a set of coroutines.
	dispatcher interface {
		// ExecuteUntilAllBlocked executes coroutines one by one in deterministic order
		// until all of them are completed or blocked on Channel or Selector or timeout is reached.
		ExecuteUntilAllBlocked(deadlockDetectionTimeout time.Duration) (err error)
		// IsDone returns true when all of coroutines are completed
		IsDone() bool
		IsClosed() bool
		IsExecuting() bool
		Close()             // Destroys all coroutines without waiting for their completion
		StackTrace() string // Stack trace of all coroutines owned by the Dispatcher instance

		// NewCoroutine creates a new coroutine. To be called from within another coroutine.
		// Used by the interceptors.
		NewCoroutine(ctx Context, name string, highPriority bool, f func(ctx Context)) Context
	}

	// Workflow is an interface that any workflow should implement.
	// Code of a workflow must be deterministic. It must use workflow.Channel, workflow.Selector, and workflow.Go instead of
	// native channels, select and go. It also must not use range operation over map as it is randomized by go runtime.
	// All time manipulation should use current time returned by GetTime(ctx) method.
	// Note that workflow.Context is used instead of context.Context to avoid use of raw channels.
	workflow interface {
		Execute(ctx Context, input *commonpb.Payloads) (result *commonpb.Payloads, err error)
	}

	sendCallback struct {
		value any
		fn    func() bool // false indicates that callback didn't accept the value
	}

	receiveCallback struct {
		// false result means that callback didn't accept the value and it is still up for delivery
		fn func(v any, more bool) bool
	}

	channelImpl struct {
		name            string                  // human readable channel name
		size            int                     // Channel buffer size. 0 for non buffered.
		buffer          []any                   // buffered messages
		blockedSends    []*sendCallback         // puts waiting when buffer is full.
		blockedReceives []*receiveCallback      // receives waiting when no messages are available.
		closed          bool                    // true if channel is closed.
		recValue        *any                    // Used only while receiving value, this is used as pre-fetch buffer value from the channel.
		dataConverter   converter.DataConverter // for decode data
		env             WorkflowEnvironment
	}

	// Single case statement of the Select
	selectCase struct {
		channel     *channelImpl                       // Channel of this case.
		receiveFunc *func(c ReceiveChannel, more bool) // function to call when channel has a message. nil for send case.

		sendFunc   *func()         // function to call when channel accepted a message. nil for receive case.
		sendValue  *any            // value to send to the channel. Used only for send case.
		future     asyncFuture     // Used for future case
		futureFunc *func(f Future) // function to call when Future is ready
	}

	// Implements Selector interface
	selectorImpl struct {
		name        string
		cases       []*selectCase // cases that this select is comprised from
		defaultFunc *func()       // default case
	}

	// unblockFunc is passed evaluated by a coroutine yield. When it returns false the yield returns to a caller.
	// stackDepth is the depth of stack from the last blocking call relevant to user.
	// Used to truncate internal stack frames from thread stack.
	unblockFunc func(status string, stackDepth int) (keepBlocked bool)

	coroutineState struct {
		name         string
		dispatcher   *dispatcherImpl  // dispatcher this context belongs to
		aboutToBlock chan bool        // used to notify dispatcher that coroutine that owns this context is about to block
		unblock      chan unblockFunc // used to notify coroutine that it should continue executing.
		keptBlocked  bool             // true indicates that coroutine didn't make any progress since the last yield unblocking
		closed       atomic.Bool      // indicates that owning coroutine has finished execution
		blocked      atomic.Bool
		panicError   error // non nil if coroutine had unhandled panic
	}

	dispatcherImpl struct {
		sequence         int
		channelSequence  int // used to name channels
		selectorSequence int // used to name channels
		coroutines       []*coroutineState
		executing        bool       // currently running ExecuteUntilAllBlocked. Used to avoid recursive calls to it.
		mutex            sync.Mutex // used to synchronize executing
		closed           bool
		interceptor      WorkflowOutboundInterceptor
		logger           log.Logger
		deadlockDetector *deadlockDetector
		readOnly         bool
		// allBlockedCallback is called when all coroutines are blocked,
		// returns true if the callback updated any coroutines state and there may be more work
		allBlockedCallback func() bool
		newEagerCoroutines []*coroutineState
	}

	// WorkflowOptions options passed to the workflow function
	// The current timeout resolution implementation is in seconds and uses math.Ceil() as the duration. But is
	// subjected to change in the future.
	WorkflowOptions struct {
		TaskQueueName            string
		WorkflowExecutionTimeout time.Duration
		WorkflowRunTimeout       time.Duration
		WorkflowTaskTimeout      time.Duration
		Namespace                string
		WorkflowID               string
		WaitForCancellation      bool
		WorkflowIDReusePolicy    enumspb.WorkflowIdReusePolicy
		// WorkflowIDConflictPolicy and OnConflictOptions are only used in test environment for
		// running Nexus operations as child workflow.
		WorkflowIDConflictPolicy enumspb.WorkflowIdConflictPolicy
		OnConflictOptions        *OnConflictOptions
		DataConverter            converter.DataConverter
		RootDataConverter        converter.DataConverter
		headerCodec              converter.PayloadCodec
		RetryPolicy              *commonpb.RetryPolicy
		Priority                 *commonpb.Priority
		CronSchedule             string
		ContextPropagators       []ContextPropagator
		Memo                     map[string]any
		SearchAttributes         map[string]any
		TypedSearchAttributes    SearchAttributes
		ParentClosePolicy        enumspb.ParentClosePolicy
		StaticSummary            string
		StaticDetails            string
		eventGroups              []EventGroup
		signalChannels           map[string]Channel
		requestedSignalChannels  map[string]*requestedSignalChannel
		queryHandlers            map[string]*queryHandler
		updateHandlers           map[string]*updateHandler
		// runningUpdatesHandles is a map of update handlers that are currently running.
		runningUpdatesHandles     map[string]UpdateInfo
		VersioningIntent          VersioningIntent
		VersioningOverride        VersioningOverride
		InitialVersioningBehavior ContinueAsNewVersioningBehavior
		// currentDetails is the user-set string returned on metadata query as
		// WorkflowMetadata.current_details
		currentDetails string
	}

	// ExecuteWorkflowParams parameters of the workflow invocation
	ExecuteWorkflowParams struct {
		WorkflowOptions
		WorkflowType         *WorkflowType
		Input                *commonpb.Payloads
		Header               *commonpb.Header
		dataConverter        converter.DataConverter    // context-aware DC from ExecuteChildWorkflow
		failureConverter     converter.FailureConverter // context-aware FC from ExecuteChildWorkflow
		attempt              int32                      // used by test framework to support child workflow retry
		scheduledTime        time.Time                  // used by test framework to support child workflow retry
		lastCompletionResult *commonpb.Payloads         // used by test framework to support cron
		EventGroupMarkers    []*sdk.EventGroupMarker
	}

	// decodeFutureImpl
	decodeFutureImpl struct {
		*futureImpl
		fn            any
		dataConverter converter.DataConverter // optional: if set, used instead of ctx DC
	}

	childWorkflowFutureImpl struct {
		*decodeFutureImpl             // for child workflow result
		executionFuture   *futureImpl // for child workflow execution future
	}

	nexusOperationFutureImpl struct {
		*decodeFutureImpl             // for the result
		executionFuture   *futureImpl // for the NexusOperationExecution
	}

	asyncFuture interface {
		Future
		// Used by selectorImpl
		// If Future is ready returns its value immediately.
		// If not registers callback which is called when it is ready.
		GetAsync(callback *receiveCallback) (v any, ok bool, err error)

		// Used by selectorImpl
		RemoveReceiveCallback(callback *receiveCallback)

		// This future will added to list of dependency futures.
		ChainFuture(f Future)

		// Gets the current value and error.
		// Make sure this is called once the future is ready.
		GetValueAndError() (v any, err error)

		Set(value any, err error)
	}

	requestedSignalChannel struct {
		options SignalChannelOptions
	}

	queryHandler struct {
		fn            any
		queryType     string
		dataConverter converter.DataConverter
		options       QueryHandlerOptions
	}

	// updateSchedulerImpl adapts the coro dispatcher to the UpdateScheduler interface
	updateSchedulerImpl struct {
		dispatcher dispatcher
	}
)

