func (m *mockWrapper) getNexusMockReturn(
	ctx any,
	operation string,
	input any,
	options any,
) (retArgs mock.Arguments) {
	if _, ok := m.env.expectedNexusMockCalls[m.name]; !ok {
		// no mock
