	wfOptions.VersioningIntent = cwo.VersioningIntent
	wfOptions.VersioningOverride = cwo.VersioningOverride
	wfOptions.StaticSummary = cwo.StaticSummary
	wfOptions.StaticDetails = cwo.StaticDetails
