// LocalVar is a value local to a single workflow run.
//
// Exposed as: [go.temporal.io/sdk/workflow.LocalVar]
type LocalVar[T any] struct {
	key   *workflowLocalKey
	store *workflowLocalStore
}

type workflowLocalKey struct {
	// Keep keys non-zero-sized so distinct allocations have distinct addresses.
	_ byte
}

// NewLocalVar creates a LocalVar bound to the workflow run for ctx.
//
// Exposed as: [go.temporal.io/sdk/workflow.NewLocalVar]
func NewLocalVar[T any](ctx Context) LocalVar[T] {
	return LocalVar[T]{
		key:   &workflowLocalKey{},
		store: getWorkflowLocalStore(ctx),
	}
}

// Get returns the value associated with v in the workflow run for ctx, or the
// zero value of T if v has not been set.
func (v LocalVar[T]) Get(ctx Context) T {
	store := v.storeFor(ctx)
	value, ok := store.values[v.key]
	if !ok || value == nil {
		var zero T
		return zero
	}
	return value.(T)
}

// Set associates value with v in the workflow run for ctx.
func (v LocalVar[T]) Set(ctx Context, value T) {
	store := v.storeFor(ctx)
	assertWorkflowLocalWritable(ctx)
	store.values[v.key] = value
}

func (v LocalVar[T]) storeFor(ctx Context) *workflowLocalStore {
	if v.key == nil || v.store == nil {
		panic("workflow.LocalVar is not initialized; use workflow.NewLocalVar(ctx)")
	}
	store := getWorkflowLocalStore(ctx)
	if store != v.store {
		panic("workflow.LocalVar: context belongs to a different workflow run")
	}
	return store
}

type workflowLocalStore struct {
	values map[*workflowLocalKey]any
}

type workflowLocalStoreContextKey struct{}

func workflowContextWithLocalStore(ctx Context) Context {
	return WithValue(ctx, workflowLocalStoreContextKey{}, &workflowLocalStore{
		values: make(map[*workflowLocalKey]any),
	})
}

func getWorkflowLocalStore(ctx Context) *workflowLocalStore {
	if ctx == nil {
		panic("workflow.LocalVar: nil workflow context")
	}
	store, ok := ctx.Value(workflowLocalStoreContextKey{}).(*workflowLocalStore)
	if !ok {
		panic("workflow.LocalVar: context is not associated with a workflow run")
	}
	return store
}

func assertWorkflowLocalWritable(ctx Context) {
	state, _ := ctx.Value(coroutinesContextKey).(*coroutineState)
	if state != nil && state.dispatcher.getIsReadOnly() {
		panic(panicIllegalAccessCoroutineState)
	}
}

package internal

import (
	"crypto/sha256"
	"encoding/binary"
	"io"
	"math/rand/v2"
)

const seedVersion = "temporal.sdk.random.v1"

func deriveSeed(runID, name string) [32]byte {
	// The separators keep ("ab", "c") from colliding with ("a", "bc")
	return sha256.Sum256([]byte(seedVersion + "\x00" + runID + "\x00" + name))
}

func getRandomStream(randoms map[string]*workflowRandomStream, runID, name string) *workflowRandomStream {
	if r, ok := randoms[name]; ok {
		return r
	}

	randoms[name] = &workflowRandomStream{source: rand.NewChaCha8(deriveSeed(runID, name))}
	return randoms[name]
}

func reseedRandoms(randoms map[string]*workflowRandomStream, newRunID string) {
	for name, r := range randoms {
		r.reseed(deriveSeed(newRunID, name)) // Seed in place so workflow held references are updated
	}
}

// Exposed as: [go.temporal.io/sdk/workflow.WorkflowRandomStream]
type WorkflowRandomStream interface {
	rand.Source
	io.Reader
}

// workflowRandomStream wraps ChaCha8 instead of embedding it so callers cannot
// mutate a shared named stream through Seed or UnmarshalBinary.
//
// Uint64 and Read must produce a stable, well-defined interleaving on their
// own: ChaCha8.Read and ChaCha8.Uint64 leave the interleaving of the two
// undefined (see [ChaCha8.Read]), so only ChaCha8.Read is ever called
// directly; Uint64 is implemented on top of it.
//
// [ChaCha8.Read]: https://go.dev/src/math/rand/v2/chacha8.go#L48
type workflowRandomStream struct {
	source *rand.ChaCha8
}

func (r *workflowRandomStream) Uint64() uint64 {
	var buf [8]byte
	_, _ = r.source.Read(buf[:]) // ChaCha8.Read always returns len(p), nil
	return binary.LittleEndian.Uint64(buf[:])
}

func (r *workflowRandomStream) Read(p []byte) (int, error) {
	return r.source.Read(p)
}

func (r *workflowRandomStream) reseed(seed [32]byte) {
	r.source.Seed(seed)
}

// Exposed as: [go.temporal.io/sdk/workflow.GetRandomStream]
func GetRandomStream(ctx Context, name string) WorkflowRandomStream {
	return GetWorkflowEnvironment(ctx).GetRandomStream(name)
}

